// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"taylor-limits-higher":{"id":"taylor-limits-higher","prerequisites":["taylor-limits","maclaurin-series","taylor-error"],"next":["asymptotic-equivalence"],"related":["big-o-little-o","lhopital"],"objectives":["看分母（或分子第一個不會消掉的項）決定每個函數要展到第幾階。","會做合成與相除的展開：$e^{\\sin x}$、$\\ln(\\cos x)$、$\\tan x=\\frac{\\sin x}{\\cos x}$。","$x\\to\\infty$ 的題先令 $t=\\frac{1}{x}$ 換成 $t\\to 0^+$；$1^\\infty$ 型先取對數再展開。"],"concept":[{"heading":"① 這一課多了什麼","body":["〈用 Taylor 求極限〉處理的是一個函數展開、減掉前幾項的題。真正難的題有三種變化：函數套函數（$e^{\\sin x}$）、相乘相除（$\\tan x$、$\\frac{1}{\\sin^2 x}$）、變數跑到 $\\infty$。這三種都還是同一個想法：把每一塊寫成多項式加上「更小的東西」，消掉之後看第一個留下來的項。","記號：$o(x^n)$ 代表「除以 $x^n$ 之後 $\\to 0$ 的東西」，例如 $x^5=o(x^4)$。它的運算規則在〈Big-O 與 little-o〉會正式整理，這一課先當成「後面還有項，但不影響答案」的記號。"]},{"heading":"② 展到第幾階：算總次數","body":["分母是 $x^4$，分子就要算到 $x^4$ 那一項為止。每一塊要展到多少，看它乘上別的因子之後會不會落在 $x^4$ 以內。例如 $\\sin^2 x$ 要到 $x^4$，因為 $\\sin x$ 從 $x$ 開始，$\\sin x$ 只要展到 $x^3$：$\\left(x-\\frac{x^3}{6}\\right)^2=x^2-\\frac{x^4}{3}+\\dots$，$x^3$ 那項乘上 $x$ 剛好到 $x^4$。","展少了：留下來的全被 $o(\\dots)$ 吃掉，看起來像 $\\frac{0}{0}$，什麼都看不到。展多了：不會錯，只是白算。"]},{"heading":"③ 合成：把內層展開代進外層","body":["$e^{\\sin x}$：先寫 $u=\\sin x=x-\\frac{x^3}{6}+\\dots$，$u$ 從 $x$ 開始，所以 $u^k$ 從 $x^k$ 開始。要到 $x^4$，外層 $e^u=1+u+\\frac{u^2}{2}+\\frac{u^3}{6}+\\frac{u^4}{24}$ 就夠，再把 $u$、$u^2$、$u^3$、$u^4$ 各自展到 $x^4$，合併同次項。","前提是內層 $\\to 0$（這裡 $\\sin x\\to 0$），外層才能用在 $0$ 附近的展開。$\\ln(\\cos x)$ 也一樣：$\\cos x-1=-\\frac{x^2}{2}+\\dots\\to 0$，套 $\\ln(1+u)=u-\\frac{u^2}{2}+\\dots$。"]},{"heading":"④ 相除：$\\frac{1}{1-w}$ 是幾何級數","body":["分母展開後長成 $1-w$（$w\\to 0$）時，用 $\\frac{1}{1-w}=1+w+w^2+\\dots$。例如 $\\frac{1}{\\cos x}=\\frac{1}{1-x^2/2+x^4/24-\\dots}=1+\\frac{x^2}{2}+\\frac{5x^4}{24}+\\dots$，再乘上 $\\sin x$ 就得到 $\\tan x=x+\\frac{x^3}{3}+\\frac{2x^5}{15}+\\dots$。"]},{"heading":"⑤ $x\\to\\infty$ 與 $1^\\infty$","body":["$x\\to\\infty$：令 $t=\\frac{1}{x}$，$t\\to 0^+$，就回到 $0$ 附近的展開。$1^\\infty$（例如 $(\\cos x)^{1/x^2}$）：寫成 $\\exp\\left(\\frac{\\ln(\\cos x)}{x^2}\\right)$，只展開指數裡的部分；指數的極限是 $L$，原極限就是 $e^L$（$\\exp$ 連續）。"]},{"heading":"為什麼可以這樣代：Peano 餘項","body":["若 $f$ 在 $0$ 有 $n$ 階導數，Taylor 定理給 $f(x)=\\sum_{k\\le n}\\frac{f^{(k)}(0)x^k}{k!}+o(x^n)$（Peano 形式的餘項）。合成時，若 $u(x)\\to 0$ 而且 $|u(x)|\\le C|x|$（$u$ 至少一階小），則 $o(u^n)=o(x^n)$：除以 $x^n$ 寫成 $\\frac{o(u^n)}{u^n}\\cdot\\left(\\frac{u}{x}\\right)^n$，前者 $\\to 0$、後者有界。這就是「內層代進外層、截到同一階」合法的原因。"],"collapsible":true}],"workedExamples":[{"title":"合成：$e^{\\sin x}$ 要到 $x^4$","prompt":"$\\lim_{x\\to 0}\\frac{e^{\\sin x}-1-x-x^2/2}{x^4}$","problemId":"burst-boss-lim-004","steps":["分母 $x^4$，所以 $e^{\\sin x}$ 要展到 $x^4$。令 $u=\\sin x=x-\\frac{x^3}{6}+o(x^4)$（$\\sin x$ 沒有 $x^4$ 項，下一項是 $x^5$）。","各次方展到 $x^4$：$u^2=x^2-\\frac{x^4}{3}+o(x^4)$，$u^3=x^3+o(x^4)$，$u^4=x^4+o(x^4)$。","代進 $e^u=1+u+\\frac{u^2}{2}+\\frac{u^3}{6}+\\frac{u^4}{24}+o(u^4)$：$1+\\left(x-\\frac{x^3}{6}\\right)+\\left(\\frac{x^2}{2}-\\frac{x^4}{6}\\right)+\\frac{x^3}{6}+\\frac{x^4}{24}+o(x^4)$。","合併：$x^3$ 項 $-\\frac{1}{6}+\\frac{1}{6}=0$；$x^4$ 項 $-\\frac{1}{6}+\\frac{1}{24}=-\\frac{1}{8}$。所以 $e^{\\sin x}=1+x+\\frac{x^2}{2}-\\frac{x^4}{8}+o(x^4)$。","分子 $=-\\frac{x^4}{8}+o(x^4)$，除以 $x^4$ $\\to-\\frac{1}{8}$。"],"answer":"$-\\frac{1}{8}$"},{"title":"相減再通分：$\\frac{1}{x^2}-\\frac{1}{\\sin^2 x}$","prompt":"$\\lim_{x\\to 0}\\left(\\frac{1}{x^2}-\\frac{1}{\\sin^2 x}\\right)$","problemId":"fd-limx-607","steps":["$\\infty-\\infty$，先通分：$\\frac{\\sin^2 x-x^2}{x^2\\sin^2 x}$。","分母：$\\sin^2 x=x^2+o(x^2)$，所以分母 $=x^4+o(x^4)$，是 $x^4$ 階。分子也要算到 $x^4$。","$\\sin x=x-\\frac{x^3}{6}+o(x^3)$，平方：$\\sin^2 x=x^2-\\frac{x^4}{3}+o(x^4)$（交叉項 $2\\cdot x\\cdot\\left(-\\frac{x^3}{6}\\right)=-\\frac{x^4}{3}$）。","分子 $=-\\frac{x^4}{3}+o(x^4)$，比值 $\\to-\\frac{1}{3}$。"],"answer":"$-\\frac{1}{3}$"},{"title":"$x\\to\\infty$：先換成 $t=\\frac{1}{x}$","prompt":"$\\lim_{x\\to\\infty}x^2\\left(\\ln\\left(1+\\frac{1}{x}\\right)-\\frac{1}{x+1}\\right)$","problemId":"depth-lim-006","steps":["令 $t=\\frac{1}{x}$，$t\\to 0^+$。$x^2=\\frac{1}{t^2}$，$\\frac{1}{x+1}=\\frac{t}{1+t}$。","前面有 $\\frac{1}{t^2}$，括號裡要展到 $t^2$（多寫一項 $t^3$ 方便看）：$\\ln(1+t)=t-\\frac{t^2}{2}+\\frac{t^3}{3}+o(t^3)$；$\\frac{t}{1+t}=t(1-t+t^2+o(t^2))=t-t^2+t^3+o(t^3)$。","相減：$\\left(-\\frac{1}{2}+1\\right)t^2+\\left(\\frac{1}{3}-1\\right)t^3+o(t^3)=\\frac{t^2}{2}-\\frac{2}{3}t^3+o(t^3)$。","乘上 $\\frac{1}{t^2}$：$\\frac{1}{2}-\\frac{2}{3}t+o(t)\\to\\frac{1}{2}$。"],"answer":"$\\frac{1}{2}$"}],"pitfalls":["內層沒有 $\\to 0$ 就套外層的 $0$ 附近展開，例如把 $e^{1+x}$ 當成 $1+(1+x)+\\dots$。","合成時 $u^2$ 只寫 $x^2$，漏了交叉項（$\\sin^2 x$ 的 $-\\frac{x^4}{3}$）。","分母只看「寫出來的」$x^2$，沒發現 $\\sin^2 x$ 讓分母其實是 $x^4$ 階。","$1^\\infty$ 直接答 $1$；要先取對數，指數的極限才是答案的關鍵。"],"voice":"b9fc607d","sections":[{"title":"多項式＋更小的東西","beats":[{"show":["每一塊 = 多項式 + 更小的東西"],"note":"消掉之後，看第一個留下來的項。","say":"難題有三種變化：函數套函數、相乘相除、變數跑到無限大。想法都一樣，每一塊寫成多項式加上更小的東西。","t":[0,11832]},{"show":["$o(x^n)$：除以 $x^n$ 之後 $\\to 0$"],"note":"例如 $x^5=o(x^4)$。","say":"小 o x 的 n 次方，意思是除以 x 的 n 次方之後還會趨近零。先把它當成：後面還有項，但不影響答案。","t":[11832,22704]},{"show":["分母是 $x^4$，分子就算到 $x^4$"],"say":"展到第幾階，看分母。分母是 x 的四次方，分子就要算到四次方那一項為止。","t":[22704,31056]},{"show":["$\\left(x-\\frac{x^3}{6}\\right)^2=x^2-\\frac{x^4}{3}+\\dots$"],"note":"$x^3$ 那項乘上 $x$，剛好到 $x^4$。","say":"sine x 從 x 開始，所以平方要到四次方，sine 只要展到三次方。交叉項給出負三分之一 x 的四次方。","t":[31056,41496]},{"show":["展少了：全被 $o$ 吃掉","展多了：不會錯，只是白算"],"say":"展少了，留下來的全被小 o 吃掉，什麼都看不到。展多了不會錯，只是白算。","t":[41496,49872]}],"check":0},{"title":"合成：$e^{\\sin x}$","beats":[{"show":["$u=\\sin x=x-\\frac{x^3}{6}+o(x^4)$"],"note":"$u$ 從 $x$ 開始，$u^k$ 從 $x^k$ 開始。","say":"函數套函數，先把內層叫做 u。u 等於 sine x，從 x 開始，所以 u 的 k 次方從 x 的 k 次方開始。","t":[49872,59976]},{"show":["$e^u=1+u+\\frac{u^2}{2}+\\frac{u^3}{6}+\\frac{u^4}{24}$"],"note":"要到 $x^4$，外層展到 $u^4$ 就夠。","say":"分母是 x 的四次方，外層 e 的 u 次方展到 u 的四次方就夠了。","t":[59976,65808]},{"show":["$u^2=x^2-\\frac{x^4}{3}$，$u^3=x^3$，$u^4=x^4$"],"note":"各自展到 $x^4$，後面都是 $o(x^4)$。","say":"再把 u 平方、u 三次方、u 四次方各自展到 x 的四次方，接著合併同次項。","t":[65808,73392]},{"show":["$x^3$ 項：$-\\frac{1}{6}+\\frac{1}{6}=0$"],"say":"三次方的項，一個是負六分之一，一個是正六分之一，剛好消掉。","t":[73392,80112]}],"predict":{"ask":"$x^4$ 項的係數合起來是？","options":[{"label":"$-\\frac{1}{8}$","correct":true},{"label":"$-\\frac{1}{6}$","why":"只看了 $\\frac{u^2}{2}$ 給的 $-\\frac{x^4}{6}$，漏了 $\\frac{u^4}{24}$ 給的 $\\frac{x^4}{24}$。"},{"label":"$\\frac{1}{24}$","why":"只算了 $\\frac{u^4}{24}$；$u^2$ 的交叉項 $-\\frac{x^4}{3}$ 除以 2 也落在 $x^4$。"}]}},{"title":"內層要先 $\\to 0$","beats":[{"show":["$e^{\\sin x}=1+x+\\frac{x^2}{2}-\\frac{x^4}{8}+o(x^4)$"],"note":"所以上一題的極限是 $-\\frac{1}{8}$。","say":"合併完，e 的 sine x 次方展開就出來了。分子剩負八分之一 x 的四次方，極限是負八分之一。","t":[80112,89880]},{"show":["內層 $\\to 0$，外層才能用 $0$ 附近的展開"],"note":"這裡 $\\sin x\\to 0$。","say":"能這樣代，前提是內層趨近零。像 e 的一加 x 次方，就不能直接套零附近的展開。","t":[89880,98472]},{"show":["$\\ln(\\cos x)$：$u=\\cos x-1=-\\frac{x^2}{2}+\\dots$"],"note":"套 $\\ln(1+u)=u-\\frac{u^2}{2}+\\dots$","say":"自然對數 cosine x 也一樣：把 cosine x 減一當成 u，它趨近零，就能套自然對數一加 u 的展開。","t":[98472,107400]}],"check":2},{"title":"相除：幾何級數","beats":[{"show":["$\\frac{1}{1-w}=1+w+w^2+\\dots$"],"note":"分母長成 $1-w$，$w\\to 0$。","say":"分母展開以後如果長成一減 w，w 趨近零，就用幾何級數把它翻上來。","t":[107400,115128]},{"show":["$\\frac{1}{\\cos x}=1+\\frac{x^2}{2}+\\frac{5x^4}{24}+\\dots$"],"say":"cosine x 是一減二分之一 x 平方再加一點，倒過來就是一加二分之一 x 平方，再加二十四分之五 x 的四次方。","t":[115128,125112]},{"show":["$\\tan x=x+\\frac{x^3}{3}+\\frac{2x^5}{15}+\\dots$"],"note":"$\\frac{1}{\\cos x}$ 再乘上 $\\sin x$。","say":"再乘上 sine x，就得到 tangent x 的展開：x 加三分之一 x 的三次方，再往後。","t":[125112,132672]}],"check":1},{"title":"相減再通分","beats":[{"show":["$\\frac{1}{x^2}-\\frac{1}{\\sin^2 x}=\\frac{\\sin^2 x-x^2}{x^2\\sin^2 x}$"],"note":"無限大減無限大，先通分。","say":"x 平方分之一減 sine 平方分之一，兩個都衝到無限大，先通分成一個分式。","t":[132672,140016]},{"show":["分母 $=x^4+o(x^4)$"],"note":"$\\sin^2 x=x^2+o(x^2)$，所以是 $x^4$ 階。","say":"分母不是看到的 x 平方而已：sine 平方也是 x 平方階，乘起來分母其實是 x 的四次方。","t":[140016,148464]}],"predict":{"ask":"分子 $\\sin^2 x-x^2$ 展到 $x^4$，極限是？","options":[{"label":"$-\\frac{1}{3}$","correct":true},{"label":"$0$","why":"只寫 $\\sin^2 x=x^2$，分子消光；交叉項 $2\\cdot x\\cdot\\left(-\\frac{x^3}{6}\\right)=-\\frac{x^4}{3}$ 才是答案。"},{"label":"$-\\frac{1}{6}$","why":"那是 $\\sin x$ 的 $x^3$ 係數；平方時交叉項要乘 2，得 $-\\frac{1}{3}$。"}]}},{"title":"$x\\to\\infty$ 與 $1^\\infty$","beats":[{"show":["令 $t=\\frac{1}{x}$，$t\\to 0^+$"],"note":"回到 $0$ 附近的展開。","say":"變數跑到無限大，就令 t 等於 x 分之一，t 從右邊趨近零，又回到熟悉的展開。","t":[148464,156312]},{"show":["$x^2\\left(\\ln\\left(1+\\frac{1}{x}\\right)-\\frac{1}{x+1}\\right)\\to\\frac{1}{2}$"],"note":"括號裡 $=\\frac{t^2}{2}-\\frac{2}{3}t^3+o(t^3)$。","say":"這一題括號裡相減剩二分之一 t 平方，再乘 t 平方分之一，極限是二分之一。","t":[156312,163824]},{"show":["$1^\\infty$：寫成 $\\exp(\\text{指數})$"],"note":"只展開指數裡的部分。","say":"一的無限大次方是不定型，不能直接答一。先取對數，只展開指數裡的部分。","t":[163824,172200]},{"show":["指數 $\\to L$，原極限 $=e^L$"],"note":"因為 $\\exp$ 連續。","say":"指數的極限算出來是 L，原來的極限就是 e 的 L 次方，因為指數函數連續。","t":[172200,179400]}],"check":3}],"checks":[{"ask":"求 $\\lim_{x\\to 0}\\frac{\\sin^2 x-x^2}{x^4}$ 時，$\\sin x$ 至少要展到哪一項？","options":[{"label":"到 $x^3$ 項","correct":true},{"label":"只要 $x$ 一項","why":"$\\sin^2 x$ 會變成 $x^2$，跟 $-x^2$ 消光，分子剩 $o(x^2)$，除以 $x^4$ 什麼都看不出來。"},{"label":"到 $x^2$ 項就夠，因為平方之後是 $x^4$","why":"$\\sin x$ 沒有 $x^2$ 項，截到 $x^2$ 等於只留 $x$；$x^4$ 的係數來自 $x\\cdot\\left(-\\frac{x^3}{6}\\right)$ 的交叉項。"}]},{"ask":"$\\lim_{x\\to 0}\\frac{\\tan x-\\sin x}{x^3}$ 是？","options":[{"label":"$\\frac{1}{2}$","correct":true},{"label":"$0$","why":"只展到一階，$\\tan x$ 和 $\\sin x$ 都是 $x$，看起來抵銷了；三階是 $\\frac{x^3}{3}-\\left(-\\frac{x^3}{6}\\right)=\\frac{x^3}{2}$。"},{"label":"$\\frac{1}{6}$","why":"漏了 $\\tan x$ 的 $\\frac{x^3}{3}$，只剩 $\\sin x$ 那邊的 $\\frac{x^3}{6}$。"}]},{"ask":"$\\ln(\\cos x)$ 展開的第一個非零項是？","options":[{"label":"$-\\frac{x^2}{2}$","correct":true},{"label":"$1-\\frac{x^2}{2}$","why":"那是 $\\cos x$ 本身。$\\ln(1+u)$ 的 $u=\\cos x-1=-\\frac{x^2}{2}+\\dots$，$\\ln$ 之後第一項就是 $u$。"},{"label":"$\\frac{x^2}{2}$","why":"符號反了：$\\cos x<1$，$\\ln(\\cos x)<0$。"}]},{"ask":"$\\lim_{x\\to 0}(\\cos x)^{1/x^2}$ 是？","options":[{"label":"$e^{-1/2}$","correct":true},{"label":"$1$","why":"$1^\\infty$ 是不定型。取對數得 $\\frac{\\ln(\\cos x)}{x^2}\\to-\\frac{1}{2}$，答案是 $e^{-1/2}$。"},{"label":"$e^{1/2}$","why":"$\\ln(\\cos x)\\approx-\\frac{x^2}{2}$ 是負的，指數的極限是 $-\\frac{1}{2}$。"}]}],"practice":[{"id":"lim-021","core":true},{"id":"depth-lim-011","core":true},{"id":"depth-lim-003","core":true},{"id":"fd-limx-607","core":true},{"id":"depth-lim-006","core":true},{"id":"world-030","core":true},{"id":"burst-boss-lim-004"},{"id":"burst-boss-lim-005"},{"id":"fd-limx-603"},{"id":"lx-hard-002"},{"id":"world-099","challenge":true,"note":"挑戰：$\\tan(\\sin x)$ 與 $\\sin(\\tan x)$ 前五階完全相同，要展到 $x^7$。"}]},"asymptotic-equivalence":{"id":"asymptotic-equivalence","prerequisites":["taylor-limits-higher","limit-trig-standard","limit-exp-log-standard","limit-at-infinity"],"next":["big-o-little-o"],"related":["taylor-limits","limit-comparison-test","improper-comparison"],"objectives":["說得出 $f\\sim g$ 的定義：$\\frac{f}{g}\\to 1$，並背熟 $x\\to 0$ 時的一組等價式。","在乘積與商裡用等價式替換，而且知道為什麼可以。","看出在相加、相減、指數裡替換為什麼會出錯，並會把差改寫成積再替換。"],"concept":[{"heading":"① 兩個函數「長得一樣快」","body":["$x\\to 0$ 時 $\\sin x$ 與 $x$ 都 $\\to 0$，而且 $\\frac{\\sin x}{x}\\to 1$：越靠近 $0$，兩者的差相對於它們本身越來越小。這種關係叫漸近等價，記作 $\\sin x\\sim x$（$x\\to 0$）。","一般定義：$x\\to a$ 時，若 $\\frac{f(x)}{g(x)}\\to 1$，就寫 $f\\sim g$。$a$ 可以是一個數，也可以是 $\\pm\\infty$；一定要說清楚 $x$ 往哪裡跑。"]},{"heading":"② 一組要背的等價式（$x\\to 0$）","body":["$\\sin x\\sim x$、$\\tan x\\sim x$、$\\arcsin x\\sim x$、$\\arctan x\\sim x$、$e^x-1\\sim x$、$\\ln(1+x)\\sim x$、$1-\\cos x\\sim\\frac{x^2}{2}$、$(1+x)^a-1\\sim ax$（$a\\ne 0$）。","它們都是〈用 Taylor 求極限〉裡展開式的第一個非零項。$x$ 可以換成任何 $\\to 0$ 的東西 $u(x)$：例如 $x\\to 0$ 時 $\\sin 3x\\sim 3x$，$\\ln(\\cos x)=\\ln(1+(\\cos x-1))\\sim\\cos x-1\\sim-\\frac{x^2}{2}$。"]},{"heading":"③ 乘積與商可以替換","body":["若 $f\\sim f_1$、$g\\sim g_1$，則 $f\\cdot g\\sim f_1\\cdot g_1$、$\\frac{f}{g}\\sim\\frac{f_1}{g_1}$。理由一行：$\\frac{f}{g}=\\frac{f}{f_1}\\cdot\\frac{f_1}{g_1}\\cdot\\frac{g_1}{g}$，頭尾兩個比值都 $\\to 1$，所以 $\\frac{f}{g}$ 與 $\\frac{f_1}{g_1}$ 有相同的極限（一邊存在，另一邊就存在）。","所以 $\\lim_{x\\to 0}\\frac{\\sin 3x\\cdot\\ln(1+2x)}{x(e^x-1)}$ 可以直接換成 $\\frac{3x\\cdot 2x}{x\\cdot x}=6$。"]},{"heading":"④ 相減不能替換","body":["$\\tan x-\\sin x$：把兩個都換成 $x$ 得到 $0$，但真正的 $\\tan x-\\sin x$ 不是 $0$，它 $\\sim\\frac{x^3}{2}$。等價只保證「比值 $\\to 1$」，前兩項一樣、後面的項不一樣；相減時前面的項抵銷，剩下的正是被替換丟掉的部分。","補救：把差改寫成積。$\\tan x-\\sin x=\\tan x\\cdot(1-\\cos x)\\sim x\\cdot\\frac{x^2}{2}=\\frac{x^3}{2}$，這樣就又能替換了。真的寫不成積，就回到 Taylor 展開。"]},{"heading":"⑤ 指數裡也不能替換","body":["$x\\to\\infty$ 時 $x+1\\sim x$，但 $\\frac{e^{x+1}}{e^x}=e$，不 $\\to 1$。等價只控制比值，不控制差；指數裡的差 $1$ 會被 $e$ 放大成倍數。對數反而比較安全：若 $f\\sim g$ 且 $g\\to 0^+$ 或 $g\\to\\infty$，則 $\\ln f\\sim\\ln g$，因為 $\\ln f-\\ln g=\\ln\\frac{f}{g}\\to 0$，而 $\\ln g$ 本身 $\\to\\pm\\infty$。"],"collapsible":true}],"workedExamples":[{"title":"乘積與商：直接替換","prompt":"$\\lim_{x\\to 0}\\frac{\\sin 3x\\cdot\\ln(1+2x)}{x(e^x-1)}$","steps":["每一個因子都 $\\to 0$，而且都是乘除關係，可以換。","$\\sin 3x\\sim 3x$，$\\ln(1+2x)\\sim 2x$，$e^x-1\\sim x$。","式子 $\\sim\\frac{(3x)(2x)}{x\\cdot x}=6$。"],"answer":"$6$"},{"title":"相減：先改寫成積","prompt":"$\\lim_{x\\to 0}\\frac{\\tan x-\\sin x}{x^3}$","problemId":"lim-013","steps":["分子是差，不能把 $\\tan x$、$\\sin x$ 都換成 $x$（那樣會得到 $0$，是錯的）。","提出 $\\tan x$：$\\tan x-\\sin x=\\tan x-\\tan x\\cdot\\cos x=\\tan x\\,(1-\\cos x)$。","現在是積：$\\tan x\\sim x$，$1-\\cos x\\sim\\frac{x^2}{2}$，所以分子 $\\sim\\frac{x^3}{2}$。","除以 $x^3$ $\\to\\frac{1}{2}$。"],"answer":"$\\frac{1}{2}$"},{"title":"$x\\to\\infty$ 的等價","prompt":"$\\lim_{x\\to\\infty}\\sqrt{x^2+1}\\cdot\\ln\\left(1+\\frac{3}{x}\\right)$","steps":["$x\\to\\infty$ 時只看 $x>0$。$\\sqrt{x^2+1}=x\\sqrt{1+1/x^2}$（$x>0$ 時 $\\sqrt{x^2}=x$），而 $\\sqrt{1+1/x^2}\\to 1$，所以 $\\sqrt{x^2+1}\\sim x$。","$u=\\frac{3}{x}\\to 0$，所以 $\\ln\\left(1+\\frac{3}{x}\\right)\\sim\\frac{3}{x}$。","乘積 $\\sim x\\cdot\\frac{3}{x}=3$。"],"answer":"$3$"}],"pitfalls":["在相加或相減裡替換，前面的項抵銷後得到錯的 $0$。","忘了寫 $x$ 往哪裡跑：$\\sin x\\sim x$ 只在 $x\\to 0$ 成立，$x\\to\\infty$ 時完全不對。","把等價用在指數裡：$x+1\\sim x$ 不代表 $e^{x+1}\\sim e^x$。","替換時漏掉係數：$\\sin 3x\\sim 3x$，不是 $\\sim x$。"],"voice":"2c1fdf84","sections":[{"title":"長得一樣快","beats":[{"show":["$x\\to 0$：$\\frac{\\sin x}{x}\\to 1$"],"note":"兩個都 $\\to 0$，而且越來越像。","say":"x 趨近零的時候，sine x 和 x 都趨近零，而且比值趨近一。越靠近零，兩者越像。","t":[0,9024]},{"show":["$\\frac{f(x)}{g(x)}\\to 1$：記作 $f\\sim g$"],"note":"這叫漸近等價。","say":"一般來說，只要 f 除以 g 趨近一，就說 f 和 g 漸近等價，用一個波浪號表示。","t":[9024,16680]},{"show":["一定要說 $x$ 往哪裡跑"],"note":"$a$ 可以是一個數，也可以是 $\\pm\\infty$。","say":"要注意寫清楚 x 往哪裡跑。sine x 等價於 x 只在 x 趨近零成立，跑到無限大就完全不對。","t":[16680,26232]}],"predict":{"ask":"$f\\sim g$ 要求的是什麼？","options":[{"label":"比值 $\\frac{f}{g}\\to 1$","correct":true},{"label":"差 $f-g\\to 0$","why":"$x\\to 0$ 時 $\\sin x$ 和 $2x$ 的差也 $\\to 0$，但比值不 $\\to 1$；等價看的是比值。"},{"label":"$f$ 和 $g$ 相等","why":"$\\sin x$ 不等於 $x$，只是越靠近 $0$ 越像，比值 $\\to 1$。"}]}},{"title":"一組要背的","beats":[{"show":["$\\sin x$、$\\tan x$、$\\arcsin x$、$\\arctan x\\sim x$"],"note":"以下都是 $x\\to 0$。","say":"x 趨近零的時候，sine、tangent，還有它們的反函數，都等價於 x。","t":[26232,33048]},{"show":["$e^x-1\\sim x$，$\\ln(1+x)\\sim x$"],"say":"e 的 x 次方減一，和自然對數一加 x，也都等價於 x。","t":[33048,38664]},{"show":["$(1+x)^a-1\\sim ax$（$a\\ne 0$）"],"say":"一加 x 的 a 次方減一，等價於 a 乘 x，a 不能是零。","t":[38664,43992]},{"show":["都是展開式的第一個非零項"],"note":"見〈用 Taylor 求極限〉。","say":"不用死背：這些都是 Taylor 展開裡第一個不是零的項。","t":[43992,49056]}],"check":0},{"title":"$x$ 換成 $u(x)$","beats":[{"show":["$x$ 可以換成任何 $\\to 0$ 的 $u(x)$"],"note":"例如 $\\sin 3x\\sim 3x$。","say":"清單裡的 x 可以換成任何趨近零的東西。sine 三 x 等價於三 x，係數要留著。","t":[49056,57336]},{"show":["$\\ln(\\cos x)=\\ln(1+(\\cos x-1))$"],"note":"$u=\\cos x-1\\to 0$。","say":"自然對數 cosine x 先湊成一加 u 的樣子，u 是 cosine x 減一，它趨近零。","t":[57336,64416]},{"show":["$\\sim\\cos x-1\\sim-\\frac{x^2}{2}$"],"say":"所以它等價於 u，也就是 cosine x 減一，再等價於負二分之一 x 平方。","t":[64416,71304]}],"check":3},{"title":"乘與除可以換","beats":[{"show":["$f\\sim f_1$、$g\\sim g_1$ ⇒ $\\frac{f}{g}\\sim\\frac{f_1}{g_1}$"],"note":"乘積也一樣。","say":"在乘積和商裡，每一個因子都可以各自換成等價的東西，極限不變。","t":[71304,77904]},{"show":["$\\frac{f}{g}=\\frac{f}{f_1}\\cdot\\frac{f_1}{g_1}\\cdot\\frac{g_1}{g}$"],"note":"頭尾兩個比值都 $\\to 1$。","say":"理由只要一行：拆成三個比值相乘，頭尾兩個都趨近一，中間那個就決定極限。","t":[77904,85824]},{"show":["$\\frac{\\sin 3x\\cdot\\ln(1+2x)}{x(e^x-1)}$","$\\sim\\frac{3x\\cdot 2x}{x\\cdot x}=6$"],"say":"例如這一題，分子換成三 x 乘二 x，分母換成 x 乘 x，答案是六。","t":[85824,92856]}],"check":2},{"title":"相減不能換","beats":[{"show":["$\\tan x-\\sin x$：都換成 $x$ 得 $0$？"],"note":"錯：其實 $\\tan x-\\sin x\\sim\\frac{x^3}{2}$。","say":"tangent x 減 sine x，兩個都換成 x 會得到零。可是它真的不是零。","t":[92856,100032]},{"show":["等價只保證比值 $\\to 1$"],"note":"相減時前面的項抵銷，剩下的正是被丟掉的。","say":"等價只管比值，前面的項一樣、後面的不一樣。相減把前面消掉，剩下的正是替換時丟掉的部分。","t":[100032,110328]},{"show":["補救：差改寫成積"],"note":"$\\tan x-\\sin x=\\tan x\\,(1-\\cos x)$","say":"補救的辦法是把差改寫成積：提出 tangent x，剩下一減 cosine x。寫不成積，就回到 Taylor 展開。","t":[110328,120264]}],"predict":{"ask":"$\\tan x\\,(1-\\cos x)$ 等價於？","options":[{"label":"$\\frac{x^3}{2}$","correct":true},{"label":"$0$","why":"那是在相減裡直接替換的結果；改寫成積之後，$\\tan x\\sim x$、$1-\\cos x\\sim\\frac{x^2}{2}$。"},{"label":"$x^3$","why":"$1-\\cos x\\sim\\frac{x^2}{2}$，不是 $x^2$；少了二分之一。"}]}},{"title":"指數裡與 $x\\to\\infty$","beats":[{"show":["$x\\to\\infty$：$x+1\\sim x$","但 $\\frac{e^{x+1}}{e^x}=e$"],"note":"等價只控制比值，不控制差。","say":"x 加一和 x 等價，但放進指數，比值是 e，不是一。指數裡的差一，被放大成倍數了。","t":[120264,129600]},{"show":["$\\sqrt{x^2+1}\\sim x$（$x>0$）"],"note":"$\\sqrt{1+1/x^2}\\to 1$。","say":"x 趨近無限大，只看 x 大於零。根號 x 平方加一，提出 x 之後剩下的部分趨近一，所以等價於 x。","t":[129600,140136]},{"show":["$\\ln\\left(1+\\frac{3}{x}\\right)\\sim\\frac{3}{x}$"],"note":"$u=\\frac{3}{x}\\to 0$。","say":"x 分之三趨近零，所以自然對數一加 x 分之三，等價於 x 分之三。","t":[140136,146856]},{"show":["乘積 $\\sim x\\cdot\\frac{3}{x}=3$"],"say":"兩個因子相乘，x 約掉，極限是三。","t":[146856,151320]}],"check":1}],"checks":[{"ask":"$x\\to 0$ 時，$1-\\cos x$ 等價於？","options":[{"label":"$\\frac{x^2}{2}$","correct":true},{"label":"$x$","why":"$\\frac{1-\\cos x}{x}\\to 0$，不是 $\\to 1$。$1-\\cos x$ 是二階小量。"},{"label":"$x^2$","why":"$\\frac{1-\\cos x}{x^2}\\to\\frac{1}{2}$，不是 $1$；要寫 $\\frac{x^2}{2}$ 比值才 $\\to 1$。"}]},{"ask":"下面哪一個替換是對的？","options":[{"label":"$\\lim_{x\\to 0}\\frac{\\sin x\\cdot(e^x-1)}{x^2}$：換成 $\\frac{x\\cdot x}{x^2}$，得 $1$","correct":true},{"label":"$\\lim_{x\\to 0}\\frac{\\sin x-x}{x^3}$：把 $\\sin x$ 換成 $x$，得 $0$","why":"這是相減。前面的 $x$ 抵銷之後，剩下的正是被丟掉的 $-\\frac{x^3}{6}$，答案是 $-\\frac{1}{6}$。"},{"label":"$x\\to\\infty$ 時 $x+1\\sim x$，所以 $\\lim\\frac{e^{x+1}}{e^x}=1$","why":"等價不能放進指數。$\\frac{e^{x+1}}{e^x}=e$。"}]},{"ask":"$\\lim_{x\\to 0}\\frac{\\ln(1+5x)}{\\arcsin 2x}$ 是？","options":[{"label":"$\\frac{5}{2}$","correct":true},{"label":"$1$","why":"兩個都「像 $x$」，但係數要留著：$\\ln(1+5x)\\sim 5x$，$\\arcsin 2x\\sim 2x$。"},{"label":"$10$","why":"這是商，不是積：$\\frac{5x}{2x}=\\frac{5}{2}$。"}]},{"ask":"$x\\to 0$ 時 $\\ln(\\cos x)$ 等價於？","options":[{"label":"$-\\frac{x^2}{2}$","correct":true},{"label":"$\\cos x$","why":"$\\cos x\\to 1$，$\\ln(\\cos x)\\to 0$，兩者比值不 $\\to 1$。要用 $\\ln(1+u)\\sim u$，$u=\\cos x-1$。"},{"label":"$\\frac{x^2}{2}$","why":"$\\cos x<1$ 時 $\\ln(\\cos x)<0$，符號是負的。"}]}],"practice":[{"id":"tb-lh-001","core":true},{"id":"tb-lh-002","core":true},{"id":"lim-030","core":true},{"id":"exam-lim-015","core":true},{"id":"lim-013","core":true},{"id":"depth-lim-010","core":true},{"id":"rel-boss-019","core":true},{"id":"lx-hard-008"},{"id":"fd-limx-608"},{"id":"lm-nr-003"},{"id":"fd-limx-606","challenge":true,"note":"挑戰：提出 $e^x$，$e^{\\tan x}-e^x=e^x\\left(e^{\\tan x-x}-1\\right)$，再用 $e^u-1\\sim u$。"}]},"big-o-little-o":{"id":"big-o-little-o","prerequisites":["asymptotic-equivalence","taylor-limits-higher","taylor-error"],"next":["stirling"],"related":[],"objectives":["分清楚 $f=o(g)$（比值 $\\to 0$）與 $f=O(g)$（被 $g$ 的常數倍控制），而且每次都說明 $x$ 往哪裡跑。","會用 $o$、$O$ 的運算規則做展開的記帳：相加取低階、相乘次數相加、$o-o$ 不是 $0$。","會用「主項 $+$ 誤差項」的寫法算出 $n\\left(\\left(1+\\frac{1}{n}\\right)^n-e\\right)$ 這類極限。"],"concept":[{"heading":"① 為什麼需要記號：替「剩下的部分」記帳","body":["Taylor 展開寫「$\\sin x=x-\\frac{x^3}{6}+\\dots$」時，那個「$\\dots$」到底多小？相乘、相除、代進別的函數之後，它會不會長大到影響答案？$o$ 與 $O$ 就是用來精確回答這個問題的記號。"]},{"heading":"② 定義（$x\\to a$，$a$ 可以是數或 $\\pm\\infty$）","body":["$f=o(g)$：$\\frac{f}{g}\\to 0$。讀作「$f$ 比 $g$ 小得多」。","$f=O(g)$：存在常數 $C$，使得在 $a$ 附近 $|f|\\le C|g|$。讀作「$f$ 最多跟 $g$ 一樣大（差一個常數倍）」。","跟上一課接起來：$f\\sim g$ 等於 $f=g+o(g)$。","方向一定要寫：$x\\to 0$ 時 $x^3=o(x^2)$（次方越高越小）；$x\\to\\infty$ 時反過來，$x^2=o(x^3)$。"]},{"heading":"③ 等號只能從左讀到右","body":["$o(x^2)$ 代表「某一個除以 $x^2$ 會 $\\to 0$ 的函數」，是一整類函數，不是一個數。所以 $x^3=o(x^2)$ 對，倒過來寫 $o(x^2)=x^3$ 沒有意義。兩個 $o(x^2)$ 也不一定是同一個函數：$o(x^2)-o(x^2)$ 還是 $o(x^2)$，不是 $0$。"]},{"heading":"④ 運算規則（$x\\to 0$，$m$、$n\\ge 0$）","body":["相加取低階：$o(x^m)+o(x^n)=o(x^{\\min(m,n)})$。常數倍不變：$c\\cdot o(x^n)=o(x^n)$。","相乘次數相加：$x^m\\cdot o(x^n)=o(x^{m+n})$，$o(x^m)\\cdot o(x^n)=o(x^{m+n})$。相除次數相減：$\\frac{o(x^n)}{x^m}=o(x^{n-m})$。","$O$ 的規則一模一樣。一個實用的對照：$o(x^n)$ 是「比 $x^n$ 小」，$O(x^{n+1})$ 是「最多跟 $x^{n+1}$ 一樣大」，後者是更精確的資訊。"]},{"heading":"⑤ $x\\to\\infty$ 的成長階梯","body":["對任何 $p>0$、$a>0$、$b>1$：$(\\ln x)^p=o(x^a)$，$x^a=o(b^x)$。也就是 對數 $\\ll$ 冪次 $\\ll$ 指數。這張表在比較判別、瑕積分、Stirling 公式裡會一直用到。"]},{"heading":"Peano 餘項與 Lagrange 餘項給的是哪一種","body":["$f$ 在 $0$ 有 $n$ 階導數：$f(x)=T_n(x)+o(x^n)$（Peano）。若 $f^{(n+1)}$ 在 $0$ 附近有界，由 Lagrange 餘項 $\\frac{f^{(n+1)}(c)x^{n+1}}{(n+1)!}$ 得到更強的 $f(x)=T_n(x)+O(x^{n+1})$。〈Taylor 誤差〉裡的誤差上界，就是把 $O$ 裡的常數 $C$ 具體算出來。"],"collapsible":true}],"workedExamples":[{"title":"相乘時的記帳","prompt":"把 $e^x\\sin x$ 展開到 $x^3$，並求 $\\lim_{x\\to 0}\\frac{e^x\\sin x-x-x^2}{x^3}$","steps":["$\\sin x$ 從 $x$ 開始，所以 $e^x$ 只要展到 $x^2$：$e^x=1+x+\\frac{x^2}{2}+o(x^2)$；$\\sin x=x-\\frac{x^3}{6}+o(x^3)$。","相乘並逐項記帳：$1\\cdot\\left(x-\\frac{x^3}{6}\\right)+x\\cdot x+\\frac{x^2}{2}\\cdot x=x+x^2+\\frac{x^3}{2}-\\frac{x^3}{6}$。","誤差項：$o(x^2)\\cdot x=o(x^3)$；$1\\cdot o(x^3)=o(x^3)$；$x\\cdot\\left(-\\frac{x^3}{6}\\right)$ 是 $x^4$，屬於 $o(x^3)$。全部合起來是 $o(x^3)$。","所以 $e^x\\sin x=x+x^2+\\frac{x^3}{3}+o(x^3)$，所求極限是 $\\frac{1}{3}$。"],"answer":"$e^x\\sin x=x+x^2+\\frac{x^3}{3}+o(x^3)$；極限 $\\frac{1}{3}$"},{"title":"$x\\to\\infty$：主項與下一項","prompt":"$x\\to\\infty$ 時，$f(x)=\\frac{x^3+\\ln x}{2x+\\sqrt{x}}$。找主項，並說明誤差多大。","steps":["提出最大的：$f=\\frac{x^2}{2}\\cdot\\frac{1+(\\ln x)/x^3}{1+1/(2\\sqrt{x})}$。","$w=\\frac{1}{2\\sqrt{x}}\\to 0$，$\\frac{1}{1+w}=1-w+O(w^2)=1-\\frac{1}{2\\sqrt{x}}+O\\left(\\frac{1}{x}\\right)$。又 $\\frac{\\ln x}{x^3}=o\\left(\\frac{1}{x}\\right)$（成長階梯）。","相乘：$f=\\frac{x^2}{2}\\left(1-\\frac{1}{2\\sqrt{x}}+O\\left(\\frac{1}{x}\\right)\\right)=\\frac{x^2}{2}-\\frac{x^{3/2}}{4}+O(x)$。","所以 $f\\sim\\frac{x^2}{2}$，而且 $f-\\frac{x^2}{2}\\sim-\\frac{x^{3/2}}{4}$。"],"answer":"$f=\\frac{x^2}{2}-\\frac{x^{3/2}}{4}+O(x)$"},{"title":"經典：$\\left(1+\\frac{1}{n}\\right)^n$ 離 $e$ 多遠","prompt":"$\\lim_{n\\to\\infty}n\\left(\\left(1+\\frac{1}{n}\\right)^n-e\\right)$","problemId":"world-091","steps":["寫成指數：$\\left(1+\\frac{1}{n}\\right)^n=\\exp\\left(n\\ln\\left(1+\\frac{1}{n}\\right)\\right)$。","$t=\\frac{1}{n}\\to 0$，$\\ln(1+t)=t-\\frac{t^2}{2}+O(t^3)$，所以 $n\\ln\\left(1+\\frac{1}{n}\\right)=1-\\frac{1}{2n}+O\\left(\\frac{1}{n^2}\\right)$。","$\\exp(1+h)=e\\cdot e^h$，$h=-\\frac{1}{2n}+O\\left(\\frac{1}{n^2}\\right)\\to 0$，$e^h=1+h+O(h^2)=1-\\frac{1}{2n}+O\\left(\\frac{1}{n^2}\\right)$。","所以 $\\left(1+\\frac{1}{n}\\right)^n-e=-\\frac{e}{2n}+O\\left(\\frac{1}{n^2}\\right)$，乘上 $n$ $\\to-\\frac{e}{2}$。"],"answer":"$-\\frac{e}{2}$"}],"pitfalls":["沒寫 $x$ 往哪裡跑：$x^2=o(x)$ 在 $x\\to 0$ 對、在 $x\\to\\infty$ 錯。","把 $o(x^2)-o(x^2)$ 寫成 $0$。","相乘時次數相乘：$x^3\\cdot o(x^2)$ 是 $o(x^5)$，不是 $o(x^6)$。","把 $o(\\dots)$ 寫到等號左邊再倒推，例如由 $o(x)=x^2$ 推出別的結論。"],"voice":"3933f0e0","sections":[{"title":"替剩下的記帳","beats":[{"show":["$\\sin x=x-\\frac{x^3}{6}+\\dots$","那個 $\\dots$ 有多小？"],"say":"Taylor 展開最後那串點點點到底多小？乘一乘、代進別的函數之後，會不會長大到影響答案？","t":[0,9432]},{"show":["$f=o(g)$：$\\frac{f}{g}\\to 0$"],"note":"$f$ 比 $g$ 小得多。","say":"小 o 的意思是 f 除以 g 趨近零，也就是 f 比 g 小得多。","t":[9432,14712]},{"show":["$f=O(g)$：$|f|\\le C|g|$"],"note":"在 $a$ 附近，差一個常數倍。","say":"大 O 是說，在那一點附近，f 的大小最多是 g 的常數倍，最多跟 g 一樣大。","t":[14712,22008]},{"show":["$x\\to 0$：$x^3=o(x^2)$","$x\\to\\infty$：$x^2=o(x^3)$"],"note":"方向一定要寫。","say":"x 趨近零的時候，次方越高越小；趨近無限大就反過來。所以一定要寫 x 往哪裡跑。","t":[22008,31056]}],"check":0},{"title":"等號只能往右讀","beats":[{"show":["$o(x^2)$ 是一整類函數"],"note":"不是一個數。","say":"小 o x 平方代表的是某一個除以 x 平方會趨近零的函數，是一整類，不是一個固定的東西。","t":[31056,39408]},{"show":["$x^3=o(x^2)$ 對","$o(x^2)=x^3$ 沒有意義"],"say":"所以這個等號只能從左讀到右：x 三次方屬於這一類，倒過來寫就沒有意義。","t":[39408,46704]},{"show":["兩個 $o(x^2)$ 不一定是同一個"],"say":"式子裡出現兩次小 o x 平方，它們不一定是同一個函數，相減不會剛好抵銷。","t":[46704,54216]}],"check":1},{"title":"運算規則","beats":[{"show":["$o(x^m)+o(x^n)=o(x^{\\min(m,n)})$"],"note":"相加取低階；常數倍不變。","say":"x 趨近零時，相加取比較低的那一階，乘上常數也不變。","t":[54216,60336]},{"show":["$x^m\\cdot o(x^n)=o(x^{m+n})$"],"note":"相乘：次數相加。","say":"相乘的時候，次數相加。兩個小 o 相乘也一樣是次數相加。","t":[60336,67416]},{"show":["$\\frac{o(x^n)}{x^m}=o(x^{n-m})$"],"note":"相除：次數相減。","say":"相除就是次數相減。大 O 的規則一模一樣。","t":[67416,72624]},{"show":["$O(x^{n+1})$ 比 $o(x^n)$ 精確"],"say":"對照一下：小 o x 的 n 次方只說比它小，大 O x 的 n 加一次方說最多跟它一樣大，資訊更精確。","t":[72624,81768]}],"check":2},{"title":"相乘時記帳","beats":[{"show":["$e^x\\sin x$ 展到 $x^3$"],"note":"$\\sin x$ 從 $x$ 開始，$e^x$ 展到 $x^2$ 就夠。","say":"把 e 的 x 次方乘 sine x 展到三次方。sine x 從 x 開始，所以 e 的 x 次方只要展到平方。","t":[81768,90720]},{"show":["$1\\cdot\\left(x-\\frac{x^3}{6}\\right)+x\\cdot x+\\frac{x^2}{2}\\cdot x$"],"say":"逐項相乘，只留三次方以內的：一乘 sine 的兩項，x 乘 x，二分之一 x 平方乘 x。","t":[90720,99072]},{"show":["誤差合起來是 $o(x^3)$"],"note":"例：$o(x^2)\\cdot x=o(x^3)$。","say":"誤差也要記帳：小 o x 平方乘 x 是小 o x 三次方，x 的四次方也屬於它。全部合起來還是小 o x 三次方。","t":[99072,110016]}],"predict":{"ask":"$x^3$ 的係數是？","options":[{"label":"$\\frac{1}{3}$","correct":true},{"label":"$\\frac{1}{2}$","why":"只算了 $\\frac{x^2}{2}\\cdot x$，漏了 $\\sin x$ 自己的 $-\\frac{x^3}{6}$。"},{"label":"$-\\frac{1}{6}$","why":"只看了 $\\sin x$ 的三次項；$e^x$ 的 $\\frac{x^2}{2}$ 乘上 $x$ 也是三次。"}]}},{"title":"$x\\to\\infty$ 的階梯","beats":[{"show":["對數 $\\ll$ 冪次 $\\ll$ 指數"],"note":"$p>0$、$a>0$、$b>1$。","say":"x 趨近無限大，對數比任何正冪次慢，冪次又比任何指數慢。","t":[110016,116400]},{"show":["$(\\ln x)^p=o(x^a)$，$x^a=o(b^x)$"],"say":"寫成小 o：自然對數的 p 次方比 x 的 a 次方小得多，x 的 a 次方又比 b 的 x 次方小得多。","t":[116400,124560]},{"show":["$\\frac{x^3+\\ln x}{2x+\\sqrt{x}}=\\frac{x^2}{2}-\\frac{x^{3/2}}{4}+O(x)$"],"note":"$\\frac{\\ln x}{x^3}=o\\left(\\frac{1}{x}\\right)$，靠的就是這張表。","say":"這張表拿來找主項：這個分式的主項是二分之一 x 平方，下一項是負四分之一 x 的二分之三次方。","t":[124560,133728]}],"check":3},{"title":"離 $e$ 多遠","beats":[{"show":["$\\left(1+\\frac{1}{n}\\right)^n=\\exp\\left(n\\ln\\left(1+\\frac{1}{n}\\right)\\right)$"],"say":"一加 n 分之一的 n 次方會趨近 e，可是離 e 多遠？先寫成指數。","t":[133728,140616]},{"show":["$n\\ln\\left(1+\\frac{1}{n}\\right)=1-\\frac{1}{2n}+O\\left(\\frac{1}{n^2}\\right)$"],"note":"$t=\\frac{1}{n}$，$\\ln(1+t)=t-\\frac{t^2}{2}+O(t^3)$。","say":"令 t 等於 n 分之一，展開自然對數再乘 n，得到一減二 n 分之一，再加大 O 的誤差。","t":[140616,148512]},{"show":["$e^h=1+h+O(h^2)$"],"note":"$h=-\\frac{1}{2n}+O\\left(\\frac{1}{n^2}\\right)\\to 0$。","say":"e 的一加 h 次方是 e 乘 e 的 h 次方，h 趨近零，就再展開一次。","t":[148512,154776]}],"predict":{"ask":"$\\lim n\\left(\\left(1+\\frac{1}{n}\\right)^n-e\\right)$ 是？","options":[{"label":"$-\\frac{e}{2}$","correct":true},{"label":"$0$","why":"只知道 $\\left(1+\\frac{1}{n}\\right)^n\\to e$；差是 $-\\frac{e}{2n}$，乘上 $n$ 不是 $0$。"},{"label":"$-\\frac{1}{2}$","why":"忘了前面的 $e$：$\\exp(1+h)=e\\cdot e^h$，差是 $e\\cdot\\left(-\\frac{1}{2n}\\right)$。"}]}}],"checks":[{"ask":"$x\\to 0$ 時，下面哪一個成立？","options":[{"label":"$x^3=o(x^2)$","correct":true},{"label":"$x^2=o(x^3)$","why":"$\\frac{x^2}{x^3}=\\frac{1}{x}\\to\\infty$。在 $0$ 附近次方越高越小，方向反了。"},{"label":"$x=o(x)$","why":"$\\frac{x}{x}=1$，不 $\\to 0$。$o$ 是「小得多」，不是「一樣大」。"}]},{"ask":"$x\\to 0$ 時，$o(x^2)-o(x^2)$ 等於？","options":[{"label":"$o(x^2)$","correct":true},{"label":"$0$","why":"兩個 $o(x^2)$ 代表兩個不一定相同的函數，只知道各自比 $x^2$ 小得多，相減不會剛好抵銷。"},{"label":"$o(x^4)$","why":"相減不會讓階數變高；只能保證結果仍然比 $x^2$ 小得多。"}]},{"ask":"$x\\to 0$ 時，$x^3\\cdot o(x^2)$ 等於？","options":[{"label":"$o(x^5)$","correct":true},{"label":"$o(x^6)$","why":"次數是相加，不是相乘：$x^3\\cdot x^2=x^5$。"},{"label":"沒辦法化簡，只能保留 $x^3\\cdot o(x^2)$","why":"可以化簡：$x^3\\cdot o(x^2)$ 除以 $x^5$ 等於 $\\frac{o(x^2)}{x^2}\\to 0$。"}]},{"ask":"$x\\to\\infty$ 時，下面哪一個成立？","options":[{"label":"$(\\ln x)^{10}=o(\\sqrt{x})$","correct":true},{"label":"$e^x=O(x^{100})$","why":"指數成長比任何冪次快，$\\frac{e^x}{x^{100}}\\to\\infty$，找不到常數 $C$ 壓住。"},{"label":"$\\sqrt{x}=o(\\ln x)$","why":"方向反了：對數比任何正冪次都慢，是 $\\ln x=o(\\sqrt{x})$。"}]}],"practice":[{"id":"mob-limtrap-005","core":true},{"id":"exam-lim-003","core":true},{"id":"exam-lim-007","core":true},{"id":"cx-hl-002","core":true},{"id":"world-091","core":true},{"id":"lm-nr-005"},{"id":"dm-seq-010"},{"id":"depth-lim-012"},{"id":"dm-seq-005","challenge":true,"note":"挑戰：$\\sqrt{n^2+n}=n+\\frac{1}{2}-\\frac{1}{8n}+O\\left(\\frac{1}{n^2}\\right)$，再用 $\\sin$ 的週期。"},{"id":"rel-hard-lim-010","challenge":true,"note":"挑戰：比範例 3 多展一項，誤差要算到 $O\\left(\\frac{1}{n^3}\\right)$。"}]},"stirling":{"id":"stirling","prerequisites":["big-o-little-o","asymptotic-equivalence","ibp-log-invtrig","riemann-sum-intuition"],"next":["stolz-cesaro"],"related":["wallis-product","euler-maclaurin-intro"],"objectives":["寫得出 $n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$，並說清楚「$\\sim$」保證的是比值 $\\to 1$，不是差 $\\to 0$。","用 $\\ln n!=\\sum\\ln k$ 與 $\\int\\ln x\\,dx$ 的比較，說出 $\\left(\\frac{n}{e}\\right)^n$ 從哪裡來。","用 Stirling 算含階乘的極限：$\\frac{(n!)^{1/n}}{n}$、中央二項式係數 $\\binom{2n}{n}$。"],"concept":[{"heading":"① 公式與它的意思","body":["$n\\to\\infty$ 時 $n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$，也就是兩者的比值 $\\to 1$。","$n=10$：$10!=3{,}628{,}800$，右邊約 $3{,}598{,}696$，比值約 $1.0084$，相對誤差不到 1%。但差約 $30{,}104$，而且 $n$ 越大差越大（$n=20$ 時差約 $10^{16}$）。Stirling 是相對誤差小，不是絕對誤差小，所以只能用在乘、除、開 $n$ 次方這類看比值的地方。"],"tex":["n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^{n}"]},{"heading":"② $\\left(\\frac{n}{e}\\right)^n$ 從哪裡來（直覺，不是證明）","body":["取對數，乘積變成和：$\\ln n!=\\ln 1+\\ln 2+\\dots+\\ln n$。這是 $y=\\ln x$ 在 $x=1,2,\\dots,n$ 的高度相加，很像 $\\int_1^n\\ln x\\,dx=n\\ln n-n+1$。","所以 $\\ln n!\\approx n\\ln n-n$，取指數得 $n!\\approx\\left(\\frac{n}{e}\\right)^n$ 這個量級。再用梯形法修正（端點各算一半）會多出 $\\frac{1}{2}\\ln n$，也就是 $\\sqrt{n}$ 這個因子。","這只是直覺：它說明了 $n^n$、$e^{-n}$、$\\sqrt{n}$ 三個因子，但沒有算出常數 $\\sqrt{2\\pi}$，也沒有證明誤差真的趨近 $0$。"]},{"heading":"③ 怎麼用：先把階乘換掉，再化簡","body":["因為 $\\sim$ 可以在乘積與商裡替換（〈漸近等價〉），含階乘的比值可以把每個 $n!$ 換成 $\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$，然後把 $e$ 的次方、$n$ 的次方各自合併。開 $n$ 次方也可以：若 $a_n\\sim b_n$，則 $\\left(\\frac{a_n}{b_n}\\right)^{1/n}\\to 1$。","最常用的兩個結果：$(n!)^{1/n}\\sim\\frac{n}{e}$，以及 $\\binom{2n}{n}\\sim\\frac{4^n}{\\sqrt{\\pi n}}$。"]},{"heading":"證明的骨架：常數是怎麼定出來的","body":["令 $d_n=\\ln n!-\\left(n+\\frac{1}{2}\\right)\\ln n+n$。用梯形法估 $\\int_k^{k+1}\\ln x\\,dx$ 的誤差，可以證明 $d_n-d_{n+1}=O\\left(\\frac{1}{n^2}\\right)$，而 $\\sum\\frac{1}{n^2}$ 收斂，所以 $d_n$ 收斂到某個常數 $C$，也就是 $n!\\sim e^C\\sqrt{n}\\left(\\frac{n}{e}\\right)^n$。","常數 $e^C=\\sqrt{2\\pi}$ 要另外決定：把這個式子代進〈Wallis 乘積〉$\\frac{\\pi}{2}=\\lim$ 的那個比值，就解出 $e^C$。更精細的展開 $n!=\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n\\left(1+\\frac{1}{12n}+O\\left(\\frac{1}{n^2}\\right)\\right)$ 來自〈Euler–Maclaurin 入門〉。"],"collapsible":true}],"workedExamples":[{"title":"相對誤差 vs. 絕對誤差","prompt":"比較 $10!$ 與 $\\sqrt{20\\pi}\\left(\\frac{10}{e}\\right)^{10}$。","steps":["$10!=3{,}628{,}800$。","$\\sqrt{20\\pi}\\approx 7.927$，$\\left(\\frac{10}{e}\\right)^{10}\\approx 453{,}999.3$，相乘約 $3{,}598{,}695.6$。","比值 $\\frac{3{,}628{,}800}{3{,}598{,}695.6}\\approx 1.0084$；差 $\\approx 30{,}104$。","比值已經很接近 $1$（實際上 $\\approx 1+\\frac{1}{12\\cdot 10}$），但差一點都不小。"],"answer":"比值約 $1.0084$，差約 $30{,}104$"},{"title":"開 $n$ 次方","prompt":"$\\lim_{n\\to\\infty}\\frac{(n!)^{1/n}}{n}$","problemId":"cx-hl-004","steps":["$n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$，開 $n$ 次方：$(n!)^{1/n}$ 與 $(2\\pi n)^{1/(2n)}\\cdot\\frac{n}{e}$ 的比值 $\\to 1$。","$(2\\pi n)^{1/(2n)}=\\exp\\left(\\frac{\\ln(2\\pi n)}{2n}\\right)$，而 $\\frac{\\ln(2\\pi n)}{2n}\\to 0$（對數 $\\ll$ 冪次），所以這個因子 $\\to 1$。","剩下 $\\frac{n/e}{n}=\\frac{1}{e}$。"],"answer":"$\\frac{1}{e}$"},{"title":"中央二項式係數","prompt":"證明 $\\binom{2n}{n}\\sim\\frac{4^n}{\\sqrt{\\pi n}}$，並求 $\\lim\\sqrt{n}\\cdot\\frac{\\binom{2n}{n}}{4^n}$。","problemId":"dm-seq-004","steps":["$\\binom{2n}{n}=\\frac{(2n)!}{(n!)^2}$。分子換成 $\\sqrt{4\\pi n}\\left(\\frac{2n}{e}\\right)^{2n}$，分母換成 $\\left(\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n\\right)^2=2\\pi n\\left(\\frac{n}{e}\\right)^{2n}$。","根號部分：$\\frac{\\sqrt{4\\pi n}}{2\\pi n}=\\frac{1}{\\sqrt{\\pi n}}$。","次方部分：$\\frac{(2n/e)^{2n}}{(n/e)^{2n}}=2^{2n}=4^n$。","所以 $\\binom{2n}{n}\\sim\\frac{4^n}{\\sqrt{\\pi n}}$，$\\sqrt{n}\\cdot\\frac{\\binom{2n}{n}}{4^n}\\to\\frac{1}{\\sqrt{\\pi}}$。"],"answer":"$\\frac{1}{\\sqrt{\\pi}}$"}],"pitfalls":["把 Stirling 用在差上，例如以為 $n!-\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n\\to 0$。","漏掉 $\\sqrt{2\\pi n}$ 只寫 $\\left(\\frac{n}{e}\\right)^n$：開 $n$ 次方時沒差，但算比值（例如 $\\binom{2n}{n}$）時答案會錯一個 $\\sqrt{n}$ 的倍數。","把 $\\left(\\frac{n}{e}\\right)^n$ 寫成 $\\frac{n^n}{e}$，$e$ 也要 $n$ 次方。","$\\binom{2n}{n}$ 的分母 $(n!)^2$ 只換一次。"],"voice":"52a75d47","sections":[{"title":"公式在說什麼","beats":[{"show":["$n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$"],"note":"$n\\to\\infty$ 時，兩者的比值 $\\to 1$。","say":"Stirling 公式說：n 很大的時候，n 階乘和右邊這一串的比值趨近一。","t":[0,6768]},{"show":["$n=10$：比值約 $1.0084$"],"note":"$10!=3{,}628{,}800$，右邊約 $3{,}598{,}696$。","say":"拿 n 等於十試試：比值大約一點零零八四，相對誤差非常小。","t":[6768,13056]},{"show":["但差約 $30{,}104$"],"note":"而且 $n$ 越大，差越大。","say":"可是兩者的絕對差很大，而且 n 越大差越大。小的是相對誤差，不是絕對誤差。","t":[13056,21552]},{"show":["只能用在看比值的地方"],"note":"乘、除、開 $n$ 次方。","say":"所以 Stirling 只能用在乘、除、開 n 次方這種看比值的地方，不能拿來算差。","t":[21552,28776]}],"check":0},{"title":"從哪裡來（直覺）","beats":[{"show":["$\\ln n!=\\ln 1+\\ln 2+\\dots+\\ln n$"],"note":"取對數，乘積變成和。","say":"先取自然對數，乘積就變成相加：自然對數曲線在一、二、一直到 n 的高度加起來。","t":[28776,37272]},{"show":["$\\int_1^n\\ln x\\,dx=n\\ln n-n+1$"],"note":"這個和很像這個積分。","say":"這一排高度相加，很像自然對數從一積到 n，積出來是 n 自然對數 n 減 n 加一。","t":[37272,44880]},{"show":["$\\ln n!\\approx n\\ln n-n$"],"note":"取指數：$n!\\approx\\left(\\frac{n}{e}\\right)^n$ 這個量級。","say":"所以自然對數 n 階乘大約是 n 自然對數 n 減 n，取指數，就是 e 分之 n 的 n 次方這個量級。","t":[44880,53472]},{"show":["梯形法修正：多出 $\\frac{1}{2}\\ln n$"],"note":"就是 $\\sqrt{n}$ 這個因子。","say":"再用梯形法把端點各算一半，多出二分之一自然對數 n，就是根號 n。常數根號二 pi 這個直覺算不出來，完整證明在全文。","t":[53472,65976]}],"check":2},{"title":"開 $n$ 次方","beats":[{"show":["先把階乘換掉，再化簡"],"note":"$\\sim$ 在乘積與商裡可以替換。","say":"用法很固定：每個 n 階乘換成 Stirling 那一串，再把 e 的次方、n 的次方各自合併。","t":[65976,73680]},{"show":["$(n!)^{1/n}\\sim(2\\pi n)^{1/(2n)}\\cdot\\frac{n}{e}$"],"say":"開 n 次方：根號二 pi n 變成二 pi n 的二 n 分之一次方，e 分之 n 的 n 次方變成 e 分之 n。","t":[73680,82056]},{"show":["$(2\\pi n)^{1/(2n)}\\to 1$"],"note":"$\\frac{\\ln(2\\pi n)}{2n}\\to 0$：對數 $\\ll$ 冪次。","say":"前面那個因子取對數，是對數除以冪次，趨近零，所以它趨近一，可以丟掉。","t":[82056,90096]}],"check":1},{"title":"中央二項式係數","beats":[{"show":["$\\binom{2n}{n}=\\frac{(2n)!}{(n!)^2}$"],"note":"分母的 $n!$ 有兩個，兩個都要換。","say":"二 n 取 n 是二 n 階乘除以 n 階乘的平方。分母有兩個 n 階乘，兩個都要換。","t":[90096,98280]},{"show":["分子 $\\sqrt{4\\pi n}\\left(\\frac{2n}{e}\\right)^{2n}$","分母 $2\\pi n\\left(\\frac{n}{e}\\right)^{2n}$"],"say":"分子把 n 換成二 n；分母是 Stirling 的平方，根號部分平方變成二 pi n。","t":[98280,105216]},{"show":["根號部分：$\\frac{\\sqrt{4\\pi n}}{2\\pi n}=\\frac{1}{\\sqrt{\\pi n}}$"],"say":"先算根號部分：根號四 pi n 除以二 pi n，等於根號 pi n 分之一。","t":[105216,112032]}],"predict":{"ask":"次方部分 $\\frac{(2n/e)^{2n}}{(n/e)^{2n}}$ 是？","options":[{"label":"$4^n$","correct":true},{"label":"$2^n$","why":"底數相除得 $2$，但指數是 $2n$：$2^{2n}=4^n$。"},{"label":"$\\frac{4^n}{e^n}$","why":"$e$ 的次方上下都是 $2n$，整個約掉了。"}]}},{"title":"合起來","beats":[{"show":["$\\binom{2n}{n}\\sim\\frac{4^n}{\\sqrt{\\pi n}}$"],"say":"兩部分乘起來，二 n 取 n 等價於四的 n 次方除以根號 pi n。","t":[112032,117960]},{"show":["$\\sqrt{n}\\cdot\\frac{\\binom{2n}{n}}{4^n}\\to\\frac{1}{\\sqrt{\\pi}}$"],"say":"所以乘上根號 n 再除以四的 n 次方，極限是根號 pi 分之一。","t":[117960,123936]},{"show":["漏了 $\\sqrt{2\\pi n}$，比值會錯"],"note":"開 $n$ 次方時沒差，算比值時差一個 $\\sqrt{n}$ 的倍數。","say":"常見的錯：只寫 e 分之 n 的 n 次方。開 n 次方時沒差，算這種比值時答案就差了根號 n 的倍數。","t":[123936,133776]}],"check":3}],"checks":[{"ask":"Stirling 公式 $n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$ 保證的是哪一件事？","options":[{"label":"$\\frac{n!}{\\sqrt{2\\pi n}\\,(n/e)^n}\\to 1$","correct":true},{"label":"$n!-\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n\\to 0$","why":"差其實越來越大：$n=10$ 時已經約 $30{,}104$。$\\sim$ 只保證比值 $\\to 1$。"},{"label":"$n$ 夠大時 $n!=\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n$","why":"右邊從來不是整數，兩者永遠不相等，只是比值越來越接近 $1$。"}]},{"ask":"$\\lim_{n\\to\\infty}\\frac{(n!)^{1/n}}{n}$ 是？","options":[{"label":"$\\frac{1}{e}$","correct":true},{"label":"$1$","why":"$(n!)^{1/n}\\sim\\frac{n}{e}$，不是 $\\sim n$；$e^{-n}$ 開 $n$ 次方剩 $\\frac{1}{e}$。"},{"label":"$0$","why":"$n!$ 比 $n^n$ 小得多是真的，但開 $n$ 次方之後差距只剩常數倍 $\\frac{1}{e}$。"}]},{"ask":"$\\ln(n!)$ 的主項是？","options":[{"label":"$n\\ln n$","correct":true},{"label":"$n$","why":"後一半的 $\\frac{n}{2}$ 項每一項都至少 $\\ln\\frac{n}{2}$，總和至少 $\\frac{n}{2}\\ln\\frac{n}{2}$，比 $n$ 大得多。"},{"label":"$n^2$","why":"每一項 $\\ln k\\le\\ln n$，$n$ 項加起來最多 $n\\ln n$，到不了 $n^2$。"}]},{"ask":"$\\binom{2n}{n}$ 漸近等價於？","options":[{"label":"$\\frac{4^n}{\\sqrt{\\pi n}}$","correct":true},{"label":"$4^n$","why":"所有 $\\binom{2n}{k}$ 加起來才是 $4^n$；中間這一項只佔其中約 $\\frac{1}{\\sqrt{\\pi n}}$ 的比例。"},{"label":"$2^n$","why":"太小了：$\\binom{2n}{n}$ 是 $2n+1$ 個加起來等於 $4^n$ 的數裡最大的，至少 $\\frac{4^n}{2n+1}$。"}]}],"practice":[{"id":"lm-nr-005","core":true},{"id":"cx-hl-004","core":true},{"id":"lm-nr-004","core":true},{"id":"world-035","core":true},{"id":"fd-limx-609","core":true},{"id":"dm-seq-004","core":true},{"id":"world-067"},{"id":"world-074","challenge":true,"note":"挑戰：倒數形式，答案是 $\\sqrt{\\pi}$；$\\sqrt{n}$ 的位置要看清楚。"}]},"stolz-cesaro":{"id":"stolz-cesaro","prerequisites":["sequence-limit","lhopital","asymptotic-equivalence"],"next":["euler-maclaurin-intro"],"related":[],"objectives":["寫得出 Stolz–Cesàro 的條件：$b_n$ 嚴格遞增而且 $\\to\\infty$，差分比的極限存在。","看到「和除以 $n$ 的次方或 $\\ln n$」就會用：相減之後和只剩最後一項。","知道反方向不成立：差分比沒有極限時，定理不說任何事。"],"concept":[{"heading":"① 數列版的 L'Hôpital","body":["數列沒有導數，但有差分 $a_{n+1}-a_n$。Stolz–Cesàro 定理說：若 $b_n$ 嚴格遞增而且 $b_n\\to\\infty$，並且差分比 $\\frac{a_{n+1}-a_n}{b_{n+1}-b_n}\\to L$，則 $\\frac{a_n}{b_n}\\to L$。$L$ 是有限數或 $\\pm\\infty$ 都可以。","注意條件全部壓在分母 $b_n$ 上，分子 $a_n$ 不需要 $\\to\\infty$。"],"tex":["\\lim_{n\\to\\infty}\\frac{a_n}{b_n}=\\lim_{n\\to\\infty}\\frac{a_{n+1}-a_n}{b_{n+1}-b_n}\\quad(\\text{右邊存在時})"]},{"heading":"② 為什麼合理（直覺，不是證明）","body":["把 $(b_n,a_n)$ 畫成平面上的點，連成折線。差分比是每一小段的斜率；$\\frac{a_n}{b_n}$ 是從原點看過去的整體斜率。如果從某段以後每一小段的斜率都接近 $L$，又因為 $b_n\\to\\infty$ 讓後面的段數越來越長，前面那些不聽話的段落佔的比重就越來越小，整體斜率也會被拉到 $L$。","直覺漏掉的是：「比重越來越小」要靠 $b_n\\to\\infty$ 才成立；$b_n$ 有界時定理會錯。"]},{"heading":"③ 最常見的用法：和除以某個東西","body":["$a_n=x_1+x_2+\\dots+x_n$ 時，$a_{n+1}-a_n=x_{n+1}$，整個和只剩最後一項。所以 $\\Sigma$ 除以 $n$、$n^p$、$\\sqrt{n}$、$\\ln n$ 的極限，都變成「最後一項除以分母的差分」。","特例 $b_n=n$：若 $x_n\\to L$，則 $\\frac{x_1+\\dots+x_n}{n}\\to L$。平均值跟著數列走，這叫 Cesàro 平均。"]},{"heading":"④ 反方向不成立","body":["$a_n=n+(-1)^n$、$b_n=n$：$\\frac{a_n}{b_n}=1+\\frac{(-1)^n}{n}\\to 1$。但差分 $a_{n+1}-a_n=1+2(-1)^{n+1}$ 在 $3$ 和 $-1$ 之間跳，差分比沒有極限。所以差分比不收斂時，不能說原極限不存在，只能換方法。"]},{"heading":"證明（$\\infty$ 型、$L$ 有限）","body":["給 $\\varepsilon>0$，取 $N$ 使 $n\\ge N$ 時差分比落在 $(L-\\varepsilon,L+\\varepsilon)$。$b_{k+1}-b_k>0$，所以可以把不等式乘上它：$(L-\\varepsilon)(b_{k+1}-b_k)<a_{k+1}-a_k<(L+\\varepsilon)(b_{k+1}-b_k)$。","對 $k=N,\\dots,n-1$ 相加，中間全部消掉：$(L-\\varepsilon)(b_n-b_N)<a_n-a_N<(L+\\varepsilon)(b_n-b_N)$。除以 $b_n$（$n$ 大時 $b_n>0$），再讓 $n\\to\\infty$：$\\frac{a_N}{b_n}$ 與 $\\frac{b_N}{b_n}$ 都 $\\to 0$，所以 $\\frac{a_n}{b_n}$ 最後落在 $[L-\\varepsilon,L+\\varepsilon]$ 裡。$\\varepsilon$ 任意，得證。","另有 $\\frac{0}{0}$ 版本：$b_n$ 嚴格遞減到 $0$、$a_n\\to 0$ 時結論一樣。"],"collapsible":true}],"workedExamples":[{"title":"和除以 $\\sqrt{n}$","prompt":"$\\lim_{n\\to\\infty}\\frac{1/\\sqrt{1}+1/\\sqrt{2}+\\dots+1/\\sqrt{n}}{\\sqrt{n}}$","problemId":"lm-st-001","steps":["$b_n=\\sqrt{n}$ 嚴格遞增到 $\\infty$，條件成立。","分子差分：$a_{n+1}-a_n=\\frac{1}{\\sqrt{n+1}}$。分母差分：$\\sqrt{n+1}-\\sqrt{n}=\\frac{1}{\\sqrt{n+1}+\\sqrt{n}}$（乘共軛）。","差分比 $=\\frac{\\sqrt{n+1}+\\sqrt{n}}{\\sqrt{n+1}}=1+\\sqrt{\\frac{n}{n+1}}\\to 1+1=2$。","所以原極限是 $2$。"],"answer":"$2$"},{"title":"平方和除以 $n^3$","prompt":"$\\lim_{n\\to\\infty}\\frac{1^2+2^2+\\dots+n^2}{n^3}$","steps":["$b_n=n^3$ 嚴格遞增到 $\\infty$。","分子差分是最後一項 $(n+1)^2$；分母差分 $(n+1)^3-n^3=3n^2+3n+1$。","差分比 $\\frac{(n+1)^2}{3n^2+3n+1}$，分子分母同除以 $n^2$，$\\to\\frac{1}{3}$。"],"answer":"$\\frac{1}{3}$","note":"同樣的算法給出 $\\frac{1^p+\\dots+n^p}{n^{p+1}}\\to\\frac{1}{p+1}$，跟 $\\int_0^1 x^p\\,dx$ 一樣。"},{"title":"分母是 $\\ln n$","prompt":"$\\lim_{n\\to\\infty}\\frac{1+1/2+\\dots+1/n}{\\ln n}$","problemId":"lm-st-003","steps":["$b_n=\\ln n$ 嚴格遞增到 $\\infty$。","分子差分 $\\frac{1}{n+1}$；分母差分 $\\ln(n+1)-\\ln n=\\ln\\left(1+\\frac{1}{n}\\right)$。","$\\ln\\left(1+\\frac{1}{n}\\right)\\sim\\frac{1}{n}$（〈漸近等價〉），差分比 $\\sim\\frac{n}{n+1}\\to 1$。","所以調和數 $H_n\\sim\\ln n$。"],"answer":"$1$"}],"pitfalls":["沒檢查 $b_n$ 嚴格遞增到 $\\infty$ 就用。","差分比沒有極限，就斷定原極限不存在。","分母差分算錯：$(n+1)^3-n^3$ 不是 $3n^2$，是 $3n^2+3n+1$（極限一樣，但中間式子要對）。","把分子的差分寫成整個和，而不是最後一項。"],"voice":"d97cb079","sections":[{"title":"數列的羅必達","beats":[{"show":["數列沒有導數，但有差分"],"note":"$a_{n+1}-a_n$","say":"函數的比值可以用羅必達，數列沒有導數，但有差分：後一項減前一項。","t":[0,7344]},{"show":["$\\lim\\frac{a_n}{b_n}=\\lim\\frac{a_{n+1}-a_n}{b_{n+1}-b_n}$"],"note":"右邊存在時。$L$ 可以是 $\\pm\\infty$。","say":"Stolz 定理說：差分比的極限如果存在，原來的比值就有同一個極限。","t":[7344,14256]},{"show":["條件：$b_n$ 嚴格遞增，$b_n\\to\\infty$"],"note":"分子 $a_n$ 不需要 $\\to\\infty$。","say":"條件全部壓在分母上：b n 嚴格遞增，而且趨近無限大。分子沒有要求。","t":[14256,22272]}],"check":0},{"title":"折線的斜率","beats":[{"show":["點 $(b_n,a_n)$ 連成折線"],"note":"差分比 = 每一小段的斜率。","say":"把 b n、a n 畫成平面上的點，連成折線。差分比就是每一小段的斜率。","t":[22272,30168]},{"show":["$\\frac{a_n}{b_n}$ = 從原點看過去的整體斜率"],"say":"原來的比值，是從原點連到最後一個點的整體斜率。","t":[30168,35448]},{"show":["後面每段斜率都接近 $L$"],"note":"前面不聽話的段落，比重越來越小。","say":"後面每一段都接近 L，前面那些亂跳的段落佔的比重越來越小，整體斜率就被拉到 L。這是直覺，不是證明。","t":[35448,46296]}],"predict":{"ask":"「前面的比重越來越小」靠的是哪個條件？","options":[{"label":"$b_n\\to\\infty$","correct":true},{"label":"$a_n\\to\\infty$","why":"定理對分子沒有要求；後面的段落越來越長，是因為橫軸 $b_n\\to\\infty$。"},{"label":"$b_n$ 遞增就夠","why":"$b_n$ 有界時，後面的段落加起來不夠長，前面的比重不會變小，定理會錯。"}]}},{"title":"和除以某個東西","beats":[{"show":["$a_n=x_1+\\dots+x_n$ ⇒ $a_{n+1}-a_n=x_{n+1}$"],"note":"整個和只剩最後一項。","say":"分子是一個和的時候，差分特別好算：前面全部消掉，只剩最後一項。","t":[46296,53592]},{"show":["$b_n=n$：$x_n\\to L$ ⇒ $\\frac{x_1+\\dots+x_n}{n}\\to L$"],"note":"Cesàro 平均：平均值跟著數列走。","say":"分母取 n，差分是一，差分比就是最後一項。數列趨近 L，平均值也趨近 L。","t":[53592,62184]},{"show":["$\\frac{1+1/2+\\dots+1/n}{\\ln n}\\to 1$"],"note":"分母差分 $\\ln\\left(1+\\frac{1}{n}\\right)\\sim\\frac{1}{n}$。","say":"分母換成自然對數 n 也行：差分比約是 n 加一分之 n，趨近一。所以調和數等價於自然對數 n。","t":[62184,72096]}],"check":2},{"title":"和除以 $\\sqrt{n}$","beats":[{"show":["$\\frac{1/\\sqrt{1}+\\dots+1/\\sqrt{n}}{\\sqrt{n}}$"],"note":"$b_n=\\sqrt{n}$ 嚴格遞增到 $\\infty$。","say":"先檢查分母：根號 n 嚴格遞增，而且趨近無限大，可以用。","t":[72096,78360]},{"show":["分子差分 $\\frac{1}{\\sqrt{n+1}}$"],"note":"最後一項。","say":"分子是和，差分就是最後一項，根號 n 加一分之一。","t":[78360,83880]},{"show":["分母差分 $\\sqrt{n+1}-\\sqrt{n}=\\frac{1}{\\sqrt{n+1}+\\sqrt{n}}$"],"note":"乘共軛。","say":"分母的差分是兩個根號相減，乘共軛，翻成兩個根號相加分之一。","t":[83880,90672]}],"predict":{"ask":"差分比 $1+\\sqrt{\\frac{n}{n+1}}$ 的極限是？","options":[{"label":"$2$","correct":true},{"label":"$1$","why":"根號裡的 $\\frac{n}{n+1}\\to 1$，那一項也 $\\to 1$，要加上前面的 $1$。"},{"label":"$\\frac{1}{2}$","why":"把差分比上下顛倒了：是分子差分除以分母差分。"}]}},{"title":"平方和除以 $n^3$","beats":[{"show":["$\\frac{1^2+2^2+\\dots+n^2}{n^3}$"],"note":"$b_n=n^3$ 嚴格遞增到 $\\infty$。","say":"再一題：平方和除以 n 的三次方，分母符合條件。","t":[90672,96048]},{"show":["$(n+1)^3-n^3=3n^2+3n+1$"],"note":"分子差分是最後一項 $(n+1)^2$。","say":"分子差分是 n 加一的平方。分母差分要展開，是三 n 平方加三 n 加一，不是只有三 n 平方。","t":[96048,105576]},{"show":["$\\frac{(n+1)^2}{3n^2+3n+1}\\to\\frac{1}{3}$"],"note":"同除以 $n^2$。","say":"分子分母同除以 n 平方，極限是三分之一，跟 x 平方從零積到一一樣。","t":[105576,112560]}],"check":1},{"title":"反方向不成立","beats":[{"show":["$a_n=n+(-1)^n$，$b_n=n$"],"note":"$\\frac{a_n}{b_n}=1+\\frac{(-1)^n}{n}\\to 1$。","say":"看這個例子：a n 是 n 加上負一的 n 次方，b n 是 n。原來的比值趨近一。","t":[112560,120216]},{"show":["差分在 $3$ 和 $-1$ 之間跳"],"note":"差分比沒有極限。","say":"可是差分一下是三、一下是負一，差分比沒有極限。","t":[120216,125880]},{"show":["差分比不收斂 ⇏ 原極限不存在"],"say":"所以差分比不收斂時，定理什麼都沒說，不能下結論，只能換方法。","t":[125880,132888]}],"check":3}],"checks":[{"ask":"使用 Stolz–Cesàro（$\\infty$ 型）需要哪個條件？","options":[{"label":"$b_n$ 嚴格遞增，而且 $b_n\\to\\infty$","correct":true},{"label":"$a_n\\to\\infty$","why":"定理對分子沒有要求；條件全部在分母 $b_n$ 上。"},{"label":"$a_n$ 與 $b_n$ 都遞增","why":"$a_n$ 可以不單調；需要單調而且 $\\to\\infty$ 的只有 $b_n$。"}]},{"ask":"$\\lim\\frac{1+2+\\dots+n}{n^2}$ 用 Stolz 算，答案是？","options":[{"label":"$\\frac{1}{2}$","correct":true},{"label":"$1$","why":"分母差分是 $(n+1)^2-n^2=2n+1$，不是 $n+1$。差分比 $\\frac{n+1}{2n+1}\\to\\frac{1}{2}$。"},{"label":"$0$","why":"分子的和也是 $n^2$ 階（$\\frac{n(n+1)}{2}$），兩者同階，比值不會 $\\to 0$。"}]},{"ask":"若 $x_n\\to 3$，則 $\\frac{x_1+x_2+\\dots+x_n}{n}$ 的極限是？","options":[{"label":"$3$","correct":true},{"label":"$0$","why":"每一項 $\\frac{x_k}{n}\\to 0$ 沒錯，但有 $n$ 項，不能逐項取極限。用 Stolz（$b_n=n$）差分比是 $x_{n+1}\\to 3$。"},{"label":"不一定存在","why":"$x_n$ 收斂時，Cesàro 平均一定收斂到同一個值，這正是 Stolz 在 $b_n=n$ 的特例。"}]},{"ask":"如果差分比 $\\frac{a_{n+1}-a_n}{b_{n+1}-b_n}$ 沒有極限，那麼 $\\frac{a_n}{b_n}$：","options":[{"label":"可能有極限，也可能沒有，要換方法","correct":true},{"label":"一定沒有極限","why":"反例 $a_n=n+(-1)^n$、$b_n=n$：差分比在 $3$ 與 $-1$ 之間跳，$\\frac{a_n}{b_n}$ 卻 $\\to 1$。"},{"label":"一定是 0","why":"沒有任何根據；定理在這個情況下什麼都沒說。"}]}],"practice":[{"id":"lm-st-001","core":true},{"id":"dm-seq-006","core":true},{"id":"lm-st-004","core":true},{"id":"lm-st-006","core":true},{"id":"lm-st-003"},{"id":"dm-seq-001"},{"id":"lx-seq-005","challenge":true,"note":"挑戰：對 $\\frac{1}{x_n^2}$ 用 Stolz，先算 $\\frac{1}{x_{n+1}^2}-\\frac{1}{x_n^2}\\to\\frac{1}{3}$。"},{"id":"dm-seq-002","challenge":true,"note":"挑戰：同一招，題目已經把差分的極限給你，最後開根號。"}]},"euler-maclaurin-intro":{"id":"euler-maclaurin-intro","prerequisites":["integral-test","riemann-sum-intuition","integration-by-parts","big-o-little-o"],"next":["improper-infinite"],"related":["stirling","basel-problem"],"objectives":["說得出「和 $\\approx$ 積分 $+$ 端點平均 $+$ 導數修正」三層，以及每一層修正的是什麼。","用前兩、三項估計和或級數的尾巴，例如 $H_n\\approx\\ln n+\\gamma+\\frac{1}{2n}$、$\\sum_{k\\ge N}\\frac{1}{k^2}\\approx\\frac{1}{N}+\\frac{1}{2N^2}+\\frac{1}{6N^3}$。","知道這是漸近展開：取前幾項配合誤差估計，不是越多項越準。"],"concept":[{"heading":"① 和與積分差多少","body":["〈積分判別〉用 $\\int f\\,dx$ 夾住 $\\sum f(k)$，只知道兩者同階。Euler–Maclaurin 公式把差距一層一層算出來（$f$ 夠光滑、$a<b$ 是整數）："],"tex":["\\sum_{k=a}^{b}f(k)=\\int_a^b f(x)\\,dx+\\frac{f(a)+f(b)}{2}+\\frac{f'(b)-f'(a)}{12}-\\frac{f'''(b)-f'''(a)}{720}+\\cdots"]},{"heading":"② 每一層在修正什麼（圖像）","body":["積分：曲線下的面積。端點平均：把長條換成梯形時，頭尾各多算了半個長條。$f'$ 項：梯形的斜邊與曲線之間還有一點彎曲造成的縫，總量跟 $f'$ 從頭到尾的變化有關，係數 $\\frac{1}{12}$。再下一層 $\\frac{1}{720}$ 修正更細的彎曲。","$f$ 是多項式時，高階導數最後全是 $0$，公式在有限項就停住，是精確等式。"]},{"heading":"③ 兩個代表性的結果","body":["調和數：$H_n=1+\\frac{1}{2}+\\dots+\\frac{1}{n}=\\ln n+\\gamma+\\frac{1}{2n}-\\frac{1}{12n^2}+\\dots$，其中 $\\gamma\\approx 0.5772$ 是 Euler–Mascheroni 常數。所以 $H_n-\\ln n\\to\\gamma$，不是 $\\to 0$。","級數的尾巴（$b\\to\\infty$，$f$ 與 $f'$ 在 $\\infty$ 都 $\\to 0$）：$\\sum_{k=N}^{\\infty}f(k)\\approx\\int_N^{\\infty}f\\,dx+\\frac{f(N)}{2}-\\frac{f'(N)}{12}$。只加前幾項、尾巴用這條估，就能把收斂很慢的級數算得很準。"]},{"heading":"④ 不是越多項越準","body":["修正項的係數（Bernoulli 數）最後會以階乘速度長大，整條無窮級數通常發散。正確用法：固定取前幾項，誤差由下一項的大小控制。這叫漸近展開——$n$ 越大，取同樣幾項就越準。"]},{"heading":"第一層修正的推導","body":["在 $[k,k+1]$ 上分部積分，取 $u=f$、$v=x-k-\\frac{1}{2}$：$\\int_k^{k+1}f\\,dx=\\frac{f(k)+f(k+1)}{2}-\\int_k^{k+1}\\left(x-k-\\frac{1}{2}\\right)f'(x)\\,dx$。","對 $k=a,\\dots,b-1$ 相加，用 $\\{x\\}$ 表示 $x$ 的小數部分，得到精確等式：$\\sum_{k=a}^b f(k)=\\int_a^b f+\\frac{f(a)+f(b)}{2}+\\int_a^b\\left(\\{x\\}-\\frac{1}{2}\\right)f'(x)\\,dx$。最後一項再分部積分一次，就生出 $\\frac{f'(b)-f'(a)}{12}$，依此類推。"],"collapsible":true}],"workedExamples":[{"title":"多項式：公式是精確的","prompt":"用 Euler–Maclaurin 求 $\\sum_{k=1}^n k^2$。","steps":["$f(x)=x^2$，$f'(x)=2x$，$f'''=0$，所以公式在 $f'$ 那項就停。","$\\int_1^n x^2\\,dx=\\frac{n^3-1}{3}$；端點平均 $\\frac{1+n^2}{2}$；導數修正 $\\frac{f'(n)-f'(1)}{12}=\\frac{2n-2}{12}$。","相加：$\\frac{n^3}{3}-\\frac{1}{3}+\\frac{1}{2}+\\frac{n^2}{2}+\\frac{n}{6}-\\frac{1}{6}=\\frac{n^3}{3}+\\frac{n^2}{2}+\\frac{n}{6}$。","整理成 $\\frac{n(n+1)(2n+1)}{6}$，正是熟悉的平方和公式。"],"answer":"$\\frac{n^3}{3}+\\frac{n^2}{2}+\\frac{n}{6}$"},{"title":"調和數 $H_{10}$","prompt":"用 $H_n\\approx\\ln n+\\gamma+\\frac{1}{2n}-\\frac{1}{12n^2}$ 估 $H_{10}$，與真值比較。","steps":["$\\ln 10\\approx 2.302585$，$\\gamma\\approx 0.577216$，$\\frac{1}{20}=0.05$，$\\frac{1}{1200}\\approx 0.000833$。","相加：$2.302585+0.577216+0.05-0.000833\\approx 2.928967$。","真值 $H_{10}=\\frac{7381}{2520}\\approx 2.928968$，誤差不到 $10^{-6}$。","只用 $\\ln 10+\\gamma\\approx 2.879801$，誤差約 $0.049$，差不多就是 $\\frac{1}{2n}$。"],"answer":"$\\approx 2.928967$（真值 $\\approx 2.928968$）"},{"title":"用尾巴估計加速級數","prompt":"只加 $\\sum_{k=1}^9\\frac{1}{k^2}$，尾巴用 Euler–Maclaurin 估，求 $\\sum_{k=1}^{\\infty}\\frac{1}{k^2}$ 的近似值。","steps":["前 9 項和 $\\approx 1.5397677$。","尾巴 $\\sum_{k=10}^{\\infty}\\frac{1}{k^2}$：$f(x)=\\frac{1}{x^2}$，$\\int_{10}^{\\infty}\\frac{dx}{x^2}=\\frac{1}{10}$，$\\frac{f(10)}{2}=\\frac{1}{200}$，$f'(x)=-\\frac{2}{x^3}$，$-\\frac{f'(10)}{12}=\\frac{2}{12\\cdot 1000}=\\frac{1}{6000}$。","尾巴 $\\approx 0.1+0.005+0.0001667=0.1051667$。","總和 $\\approx 1.6449344$；真值 $\\frac{\\pi^2}{6}\\approx 1.6449341$（〈Basel 問題〉）。只加前 9 項的誤差約 $0.105$，加上尾巴估計後誤差約 $3\\times 10^{-7}$。"],"answer":"$\\approx 1.6449344$"}],"pitfalls":["漏掉端點平均，只寫「和 $\\approx$ 積分」，誤差是 $f$ 本身的大小。","以為 $H_n\\sim\\ln n$ 代表 $H_n-\\ln n\\to 0$；其實 $\\to\\gamma$。","導數修正的符號：尾巴公式是 $-\\frac{f'(N)}{12}$，遞減函數的 $f'<0$，這一項是正的。","以為取越多修正項越準。"],"voice":"6441f20f","sections":[{"title":"和與積分差多少","beats":[{"show":["$\\sum f(k)$ 和 $\\int f\\,dx$ 同階"],"note":"積分判別只告訴我們這麼多。","say":"積分判別用積分把和夾住，只知道兩者同階。差距到底多少？","t":[0,7032]},{"show":["$\\sum_{k=a}^{b}f(k)=\\int_a^b f(x)\\,dx$","$+\\frac{f(a)+f(b)}{2}+\\dots$"],"note":"$f$ 夠光滑、$a<b$ 是整數。","say":"Euler–Maclaurin 公式一層一層算出來：先是積分，再加上兩個端點函數值的平均。","t":[7032,14688]},{"show":["$+\\frac{f'(b)-f'(a)}{12}$","$-\\frac{f'''(b)-f'''(a)}{720}+\\cdots$"],"say":"後面還有導數的修正：f prime 的變化除以十二，再來是三階導數的變化除以七百二十。","t":[14688,23136]}],"check":0},{"title":"每一層修正什麼","beats":[{"show":["積分：曲線下的面積"],"say":"第一層是積分，就是曲線底下的面積。","t":[23136,27264]},{"show":["端點平均：頭尾各半個長條"],"note":"把長條換成梯形時多出來的。","say":"把一排長條換成梯形來比，頭尾各多算了半個長條，所以要加端點的平均。","t":[27264,34464]},{"show":["$f'$ 項：斜邊和曲線之間的縫"],"note":"係數 $\\frac{1}{12}$；下一層 $\\frac{1}{720}$ 修正更細的彎曲。","say":"梯形的斜邊和曲線之間還有一點彎曲的縫，總量跟 f prime 從頭到尾的變化有關。","t":[34464,42240]},{"show":["$f$ 是多項式：有限項就停"],"note":"高階導數全是 $0$，是精確等式。","say":"如果 f 是多項式，高階導數最後全是零，公式在有限項就停住，變成精確的等式。","t":[42240,50592]}],"predict":{"ask":"$f(x)=x^2$，$\\sum_{k=1}^n$：導數修正 $\\frac{f'(n)-f'(1)}{12}$ 是？","options":[{"label":"$\\frac{2n-2}{12}$","correct":true},{"label":"$\\frac{n^2-1}{12}$","why":"代的是 $f$ 不是 $f'$；$f'(x)=2x$，所以是 $\\frac{2n-2}{12}$。"},{"label":"$0$","why":"是 $f'''=0$，不是 $f'$；$f'(x)=2x$ 頭尾不一樣。"}]}},{"title":"平方和：精確","beats":[{"show":["$\\int_1^n x^2\\,dx=\\frac{n^3-1}{3}$"],"note":"端點平均 $\\frac{1+n^2}{2}$。","say":"用公式算平方和：積分是三分之 n 三次方減一，端點平均是二分之一加 n 平方。","t":[50592,58704]},{"show":["$\\frac{n^3}{3}+\\frac{n^2}{2}+\\frac{n}{6}$"],"note":"再加導數修正 $\\frac{2n-2}{12}$，常數剛好消掉。","say":"再加上導數修正，常數項負三分之一、二分之一、負六分之一剛好抵銷。","t":[58704,66048]},{"show":["$=\\frac{n(n+1)(2n+1)}{6}$"],"say":"整理一下，正是熟悉的平方和公式。三階導數是零，所以一點誤差都沒有。","t":[66048,74424]}],"check":1},{"title":"調和數","beats":[{"show":["$H_n=\\ln n+\\gamma+\\frac{1}{2n}-\\frac{1}{12n^2}+\\dots$"],"note":"$\\gamma\\approx 0.5772$。","say":"調和數用這個公式展開：自然對數 n，加一個常數 gamma，大約零點五七七二，再加修正。","t":[74424,83280]},{"show":["$H_n-\\ln n\\to\\gamma$"],"note":"不是 $\\to 0$。","say":"所以調和數減自然對數 n，趨近的是 gamma，不是零。等價只管比值。","t":[83280,90864]},{"show":["$H_{10}$：估 $2.928967$，真值 $2.928968$"],"note":"只用 $\\ln 10+\\gamma$，誤差約 $0.049$。","say":"拿 n 等於十試試：這幾項加起來和真值只差不到十的負六次方。只用前兩項，誤差差不多就是二 n 分之一。","t":[90864,101856]}],"check":2},{"title":"用尾巴加速","beats":[{"show":["$\\sum_{k=N}^{\\infty}f(k)\\approx\\int_N^{\\infty}f\\,dx$","$+\\frac{f(N)}{2}-\\frac{f'(N)}{12}$"],"say":"級數的尾巴也能用這條估。f 遞減時 f prime 是負的，最後那一項其實是加上去。","t":[101856,110376]},{"show":["$\\sum_{k=1}^9\\frac{1}{k^2}\\approx 1.5397677$"],"note":"只加前 9 項，誤差約 $0.105$。","say":"例如 k 平方分之一，只加前九項，離真值還差零點一零五。","t":[110376,116736]},{"show":["尾巴：$\\frac{1}{10}+\\frac{1}{200}+\\frac{1}{6000}$"],"note":"積分、端點一半、導數修正。","say":"從十開始的尾巴，積分是十分之一，端點一半是兩百分之一，導數修正是六千分之一。","t":[116736,125064]}],"predict":{"ask":"總和該怎麼算？（真值 $\\frac{\\pi^2}{6}\\approx 1.6449341$）","options":[{"label":"$1.5397677+0.1051667$","correct":true},{"label":"$1.5397677+0.1$","why":"尾巴只用了積分 $\\frac{1}{10}$，漏了 $\\frac{1}{200}$ 和 $\\frac{1}{6000}$。"},{"label":"$1.5397677$","why":"那只是前 9 項；尾巴 $\\approx 0.1051667$ 還沒加。"}]}},{"title":"不是越多項越準","beats":[{"show":["係數（Bernoulli 數）以階乘速度長大"],"note":"整條無窮級數通常發散。","say":"修正項的係數最後會以階乘的速度長大，整條無窮級數通常是發散的。","t":[125064,132096]},{"show":["固定取前幾項","誤差看下一項的大小"],"say":"正確用法是固定取前幾項，誤差由下一項的大小控制。","t":[132096,137760]},{"show":["這叫漸近展開"],"note":"$n$ 越大，同樣幾項就越準。","say":"這叫漸近展開：不是項數越多越準，而是 n 越大，取同樣幾項就越準。","t":[137760,144984]}],"check":3}],"checks":[{"ask":"用 $\\int_1^n f\\,dx+\\frac{f(1)+f(n)}{2}$ 計算 $\\sum_{k=1}^n k$（$f(x)=x$），得到？","options":[{"label":"$\\frac{n(n+1)}{2}$","correct":true},{"label":"$\\frac{n^2-1}{2}$","why":"那只是積分，漏了端點平均 $\\frac{1+n}{2}$。"},{"label":"$\\frac{n^2}{2}$","why":"積分算錯了下限：$\\int_1^n x\\,dx=\\frac{n^2-1}{2}$，再加 $\\frac{1+n}{2}$ 才是 $\\frac{n(n+1)}{2}$。"}]},{"ask":"為什麼 $\\sum k^2$ 用到 $f'$ 那一項就完全正確？","options":[{"label":"$f(x)=x^2$ 的三階以上導數都是 $0$，後面的修正項全部消失","correct":true},{"label":"因為 $x^2$ 是遞增函數","why":"遞增只保證和與積分的大小關係，跟修正項會不會停沒有關係。"},{"label":"因為後面的修正項正負抵銷","why":"不是抵銷，是每一項本身就是 $0$：它們都含 $f'''$、$f^{(5)}$……"}]},{"ask":"$n\\to\\infty$ 時，$H_n-\\ln n$ 趨近？","options":[{"label":"$\\gamma\\approx 0.5772$","correct":true},{"label":"$0$","why":"$H_n\\sim\\ln n$ 只說比值 $\\to 1$，差可以趨近非零常數。"},{"label":"$\\frac{1}{2}$","why":"$\\frac{1}{2}$ 出現在 $\\frac{1}{2n}$ 這一項，它會 $\\to 0$；留下的常數是 $\\gamma$。"}]},{"ask":"Euler–Maclaurin 的修正項應該怎麼用？","options":[{"label":"取前幾項，用下一項的大小估計誤差","correct":true},{"label":"取越多項越準，取到無窮多項就是精確值","why":"修正項的係數最後以階乘速度長大，無窮級數通常發散；它是漸近展開。"},{"label":"只能用在多項式","why":"任何夠光滑的 $f$ 都能用；多項式只是剛好在有限項變成精確等式。"}]}],"practice":[{"id":"sg-est-004","core":true},{"id":"lec-12-q2d","core":true},{"id":"lm-st-002","core":true},{"id":"sg-est-003","core":true},{"id":"sg-est-005"},{"id":"an-ca-001"}]}});
